export const CURATION: Record<string, Curation> = {"cole-oxbow": {"title": {"tr": "Oxbow: Holyoke Dağı'ndan Fırtına Sonrası", "en": "The Oxbow: View from Mount Holyoke after a Thunderstorm"}, "note": {"tr": "Hudson Nehri Okulu'nun kurucusu Cole, tabloyu ikiye böler: solda fırtınalı yaban, sağda güneşli ekili tarlalar. Amerika'nın vahşi doğa ile yerleşim arasındaki seçimi.", "en": "Cole, founder of the Hudson River School, splits the canvas in two: stormy wilderness on the left, sunlit farmland on the right. America's choice between wilderness and settlement."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.75, "w": 0.125, "h": 0.25}, "title": {"tr": "Ressamın kendisi", "en": "The painter himself"}, "text": {"tr": "Aşağıda şövalesinin başında küçük bir Cole figürü.", "en": "A tiny figure of Cole at his easel, below."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.5, "w": 0.375, "h": 0.375}, "title": {"tr": "Nehir kıvrımı", "en": "The oxbow"}, "text": {"tr": "Connecticut Nehri'nin at nalı biçimli kıvrımı.", "en": "The horseshoe bend of the Connecticut River."}}, {"id": "d2", "rect": {"x": 0.0, "y": 0.0, "w": 0.5, "h": 0.375}, "title": {"tr": "Fırtına", "en": "The storm"}, "text": {"tr": "Uzaklaşan fırtına bulutları ve yağmur.", "en": "Departing storm clouds and rain."}}]}, "met-10481": {"title": {"tr": "And Dağları'nın Kalbi", "en": "Heart of the Andes"}, "note": {"tr": "Church bu dev tabloyu 1859'da tek başına sergiledi; ziyaretçiler opera dürbünüyle ayrıntıları incelemek için para ödedi. Humboldt'un doğa bilimi gözlemlerinden esinlenmiştir.", "en": "Church exhibited this huge canvas on its own in 1859; visitors paid to study its details with opera glasses. It was inspired by Humboldt's scientific observation of nature."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "Karlı zirve", "en": "Snowy summit"}, "text": {"tr": "Uzakta Chimborazo'nun karlı tepesi.", "en": "The snowy peak of Chimborazo in the distance."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Şelale", "en": "Waterfall"}, "text": {"tr": "Sağ altta dökülen şelale.", "en": "The waterfall pouring down at lower right."}}, {"id": "d2", "rect": {"x": 0.0, "y": 0.5, "w": 0.25, "h": 0.375}, "title": {"tr": "Haç", "en": "Wayside cross"}, "text": {"tr": "Solda bir haç ve iki küçük figür.", "en": "A cross and two small figures on the left."}}]}, "met-10499": {"title": {"tr": "Titan'ın Kadehi", "en": "The Titan's Goblet"}, "note": {"tr": "Cole'un en gizemli tablosu: dev bir kadehin kenarında küçük bir dünya, yelkenliler ve tapınaklar. Yorumu hâlâ tartışılır.", "en": "Cole's most enigmatic painting: a tiny world on the rim of a giant goblet, with sailing boats and temples. Its meaning is still debated."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.25, "w": 0.625, "h": 0.125}, "title": {"tr": "Kadehin içi", "en": "Inside the goblet"}, "text": {"tr": "Kadehteki göl ve yelkenliler.", "en": "The lake and sailing boats in the goblet."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.375, "w": 0.375, "h": 0.25}, "title": {"tr": "Dağlar", "en": "Mountains"}, "text": {"tr": "Solda sisli dağ silsilesi.", "en": "A misty mountain range on the left."}}]}, "met-10500": {"title": {"tr": "Tivoli Yakınlarında Sabah", "en": "A View near Tivoli (Morning)"}, "note": {"tr": "Cole İtalya yolculuğunda Roma kır bölgesinin antik su kemerlerini resmetti. Yıkıntının üstünü saran sarmaşıklar zamanın geçişini anlatır.", "en": "On his Italian journey Cole painted the ancient aqueducts of the Roman Campagna. The ivy covering the ruin tells of time's passing."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.0, "w": 0.375, "h": 0.75}, "title": {"tr": "Su kemeri", "en": "The aqueduct"}, "text": {"tr": "Sağda yıkık Roma su kemeri.", "en": "The ruined Roman aqueduct on the right."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.25, "w": 0.625, "h": 0.25}, "title": {"tr": "Sabine tepeleri", "en": "Sabine hills"}, "text": {"tr": "Uzakta sabah sisinde dağlar.", "en": "Mountains in the morning haze."}}]}, "met-10501": {"title": {"tr": "Catskill'de Erken Sonbahar", "en": "View on the Catskill—Early Autumn"}, "note": {"tr": "Cole'un yaşadığı Catskill köyünden bir görünüm. Pastoral sükunet içinde, ön plandaki anne ve çocuk ile uzaktaki dağ uyumu vurgulanır.", "en": "A view near the village of Catskill, where Cole lived. A pastoral calm, with a mother and child in the foreground and the mountains far beyond."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.875, "w": 0.25, "h": 0.125}, "title": {"tr": "Anne ve çocuk", "en": "Mother and child"}, "text": {"tr": "Ön planda çiçek toplayan figürler.", "en": "Figures gathering flowers in the foreground."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.375, "w": 0.375, "h": 0.125}, "title": {"tr": "Catskill Dağları", "en": "Catskill Mountains"}, "text": {"tr": "Uzaktaki mavi dağ silsilesi.", "en": "The distant blue mountain range."}}, {"id": "d2", "rect": {"x": 0.375, "y": 0.75, "w": 0.25, "h": 0.25}, "title": {"tr": "Dere", "en": "The creek"}, "text": {"tr": "Ağaçların arasından akan dere.", "en": "The creek winding between the trees."}}]}, "met-10496": {"title": {"tr": "Dağ Geçidi", "en": "The Mountain Ford"}, "note": {"tr": "Cole'un geç dönem tablosu. Beyaz atlı bir süvari derenin kıvrımından geçerken sarp kayalık ışığa yükselir.", "en": "A late work by Cole. A rider on a white horse fords the stream as the rocky crag rises into the light."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.75, "w": 0.25, "h": 0.125}, "title": {"tr": "Beyaz atlı", "en": "The white horse"}, "text": {"tr": "Dereyi geçen kırmızı giysili süvari.", "en": "The rider in red crossing the stream."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.125, "w": 0.375, "h": 0.375}, "title": {"tr": "Kayalık", "en": "The crag"}, "text": {"tr": "Güneşte parlayan sarp tepe.", "en": "The sheer peak catching the sun."}}]}, "met-10786": {"title": {"tr": "Kayın Ağaçları", "en": "The Beeches"}, "note": {"tr": "Durand, ağaçları ve kabuklarını doğrudan doğadan çizilmiş gibi aynı titizlikle işler. Patikadaki çoban ve koyunlar bakışı derinliğe çeker.", "en": "Durand paints the trees and their bark with the precision of studies drawn from nature. The shepherd and flock on the path draw the eye into depth."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.0, "w": 0.375, "h": 1.0}, "title": {"tr": "Kayın gövdeleri", "en": "Beech trunks"}, "text": {"tr": "Ön plandaki iri kayın ağaçları.", "en": "The great beech trees in the foreground."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.625, "w": 0.25, "h": 0.125}, "title": {"tr": "Çoban", "en": "The shepherd"}, "text": {"tr": "Patikada sürüsüyle bir çoban.", "en": "A shepherd with his flock on the path."}}]}, "met-10946": {"title": {"tr": "Kauterskill Vadisi", "en": "A Gorge in the Mountains (Kauterskill Clove)"}, "note": {"tr": "Gifford, ışığın kendisini konu alan “luminist” ressamlardandır. Güneş vadinin altın sisini doldurur, ayrıntılar havada erir.", "en": "Gifford was one of the “luminist” painters whose real subject was light. The sun fills the gorge with golden haze and details dissolve in the air."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.125, "w": 0.25, "h": 0.375}, "title": {"tr": "Altın ağaç", "en": "Golden tree"}, "text": {"tr": "Solda güneşte parlayan sonbahar ağacı.", "en": "An autumn tree glowing in the sun on the left."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.375, "w": 0.625, "h": 0.375}, "title": {"tr": "Vadi", "en": "The gorge"}, "text": {"tr": "Sise gömülü derin vadi.", "en": "The deep gorge sunk in haze."}}]}, "met-10482": {"title": {"tr": "Parthenon", "en": "The Parthenon"}, "note": {"tr": "Church 1869'da Atina'yı ziyaret etti. Akşam ışığında Parthenon, ön plandaki yıkık sütun ve dağınık mermer bloklar arasında yükselir.", "en": "Church visited Athens in 1869. The Parthenon rises in evening light among a broken column and scattered marble blocks in the foreground."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.25, "w": 0.5, "h": 0.25}, "title": {"tr": "Tapınak", "en": "The temple"}, "text": {"tr": "Akşam güneşinde Parthenon'un sütunları.", "en": "The columns of the Parthenon in evening sun."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.0, "w": 0.25, "h": 1.0}, "title": {"tr": "Yıkık sütun", "en": "Broken column"}, "text": {"tr": "Sağda tek başına kalmış Dor sütunu.", "en": "A lone Doric column on the right."}}]}, "met-10152": {"title": {"tr": "Nevada Şelalesi, Yosemite", "en": "Nevada Falls, Yosemite"}, "note": {"tr": "Bierstadt, Batı'nın görkemli doğasını Doğu'daki izleyicilere tanıtan ressamlardandı. Köpüren su, devrilmiş kütükler ve dev çamlar.", "en": "Bierstadt was among the painters who introduced the grandeur of the West to audiences in the East. Foaming water, fallen logs and giant pines."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "Şelale", "en": "The falls"}, "text": {"tr": "Uzakta dökülen Nevada Şelalesi.", "en": "Nevada Falls pouring in the distance."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.75, "w": 0.375, "h": 0.125}, "title": {"tr": "Gezginler", "en": "Travellers"}, "text": {"tr": "Kütüklerin üstündeki iki figür.", "en": "Two figures on the fallen logs."}}]}, "met-10158": {"title": {"tr": "Matterhorn'da Gün Doğumu", "en": "Sunrise on the Matterhorn"}, "note": {"tr": "Bierstadt Avrupa'da da resim yaptı. Matterhorn'un sivri tepesi ilk ışıkla pembeye dönerken vadi hâlâ gölgede.", "en": "Bierstadt painted in Europe too. The Matterhorn's sharp peak turns pink in the first light while the valley is still in shadow."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.125, "w": 0.375, "h": 0.375}, "title": {"tr": "Zirve", "en": "The summit"}, "text": {"tr": "Gün doğumunda pembeleşen Matterhorn.", "en": "The Matterhorn blushing at sunrise."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.25, "w": 0.375, "h": 0.5}, "title": {"tr": "Çamlar", "en": "Pines"}, "text": {"tr": "Soldaki karanlık çam ağaçları.", "en": "The dark pines on the left."}}]}, "met-11395": {"title": {"tr": "Golden State New York Limanı'na Giriyor", "en": "The Golden State Entering New York Harbor"}, "note": {"tr": "Lane, Amerikan denizcilik resminin ustasıdır. Çin ticaretinde çalışan hızlı “clipper” gemisi Golden State dalgalı sularda limana yaklaşır.", "en": "Lane was a master of American marine painting. The fast China-trade clipper Golden State approaches the harbour over choppy water."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.25, "w": 0.5, "h": 0.5}, "title": {"tr": "Clipper gemisi", "en": "The clipper"}, "text": {"tr": "Tüm yelkenleri açık Golden State.", "en": "The Golden State under full sail."}}, {"id": "d1", "rect": {"x": 0.125, "y": 0.625, "w": 0.125, "h": 0.25}, "title": {"tr": "Küçük tekne", "en": "Small boat"}, "text": {"tr": "Dalgalarla boğuşan küçük kayık.", "en": "A small boat battling the waves."}}, {"id": "d2", "rect": {"x": 0.875, "y": 0.5, "w": 0.125, "h": 0.25}, "title": {"tr": "Bayrak", "en": "The flag"}, "text": {"tr": "Geminin kıçındaki Amerikan bayrağı.", "en": "The American flag at the ship's stern."}}]}, "piranesi-marcellus": {"title": {"tr": "Marcellus Tiyatrosu", "en": "The Theatre of Marcellus"}, "note": {"tr": "Augustus'un yeğeni adına MÖ 13'te tamamlanan tiyatro, Orta Çağ'da kaleye, sonra saraya dönüştü. Piranesi antik kemer katlarının üstüne oturmuş Rönesans sarayını olduğu gibi çizer.", "en": "Completed in 13 BC in honour of Augustus's nephew, the theatre became a fortress in the Middle Ages and later a palace. Piranesi draws the Renaissance palace sitting on the ancient arcades just as it was."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.375, "w": 0.625, "h": 0.375}, "title": {"tr": "Antik kemerler", "en": "Ancient arcades"}, "text": {"tr": "Alt katlarda yarı gömülü Roma kemerleri; içlerine dükkânlar yerleşmiş.", "en": "Half-buried Roman arches on the lower storeys, with shops built into them."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.5, "w": 0.25, "h": 0.25}, "title": {"tr": "Kubbe", "en": "The dome"}, "text": {"tr": "Sağda Santa Maria in Campitelli'nin kubbesi.", "en": "The dome of Santa Maria in Campitelli on the right."}}]}, "met-435839": {"title": {"tr": "San Marco Meydanı", "en": "Piazza San Marco"}, "note": {"tr": "Canaletto'nun en erken Venedik görünümlerinden. Çan kulesi kompozisyonu ikiye bölerken bazilikanın kubbeleri ışıkta parlar; gölgeli tenteler sabah saatini ele verir.", "en": "One of Canaletto's earliest views of Venice. The campanile divides the composition while the basilica's domes catch the light; the shaded awnings give away the morning hour."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.0, "w": 0.25, "h": 0.625}, "title": {"tr": "Çan kulesi", "en": "The campanile"}, "text": {"tr": "San Marco'nun çan kulesi, 99 metreyle şehrin en yüksek yapısı.", "en": "San Marco's bell tower, at 99 metres the tallest building in the city."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.5, "w": 0.25, "h": 0.25}, "title": {"tr": "Bazilika", "en": "The basilica"}, "text": {"tr": "Uzakta San Marco Bazilikası'nın kubbeleri.", "en": "The domes of the Basilica of San Marco in the distance."}}, {"id": "d2", "rect": {"x": 0.0, "y": 0.75, "w": 1.0, "h": 0.25}, "title": {"tr": "Gezintiye çıkanlar", "en": "Strollers"}, "text": {"tr": "Meydanda pelerinli Venedikliler ve satıcılar.", "en": "Cloaked Venetians and vendors in the square."}}]}, "met-360270": {"title": {"tr": "Kolezyum'un Kuşbakışı", "en": "Bird's-eye View of the Colosseum"}, "note": {"tr": "Piranesi, Kolezyum'u gerçekte hiçbir noktadan görülemeyecek bir yükseklikten çizer. Yıkık sıraların içine bakan bu hayali bakış, yapının devasa ölçeğini kavratmak içindir.", "en": "Piranesi draws the Colosseum from a height no real viewpoint offered. This imagined view into the ruined tiers is meant to convey the building's colossal scale."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.375, "w": 0.5, "h": 0.25}, "title": {"tr": "Arena", "en": "The arena"}, "text": {"tr": "Ortadaki boş arena, gladyatör dövüşlerinin sahnesi.", "en": "The empty arena at the centre, stage of the gladiator fights."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.875, "w": 0.25, "h": 0.125}, "title": {"tr": "Açıklama tablosu", "en": "Key"}, "text": {"tr": "Yapının bölümlerini harflerle anlatan yazı.", "en": "The text panel explaining the building's parts by letter."}}]}, "met-337725": {"title": {"tr": "Yuvarlak Kule", "en": "The Round Tower"}, "note": {"tr": "“Hayali Hapishaneler” dizisi, hiçbir yere varmayan merdivenler ve köprülerle dolu, kâbus gibi mekânlar kurar. Piranesi bu levhaları yıllar sonra daha karanlık hâle getirerek yeniden basmıştır.", "en": "The “Imaginary Prisons” series builds nightmarish spaces full of stairs and bridges that lead nowhere. Piranesi reworked and reprinted the plates years later, making them darker still."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.125, "w": 0.375, "h": 0.5}, "title": {"tr": "Kule", "en": "The tower"}, "text": {"tr": "Ortadaki dev yuvarlak kule.", "en": "The vast round tower at the centre."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.625, "w": 0.625, "h": 0.375}, "title": {"tr": "Merdivenler", "en": "Staircases"}, "text": {"tr": "Birbirini kesen merdivenler ve köprüler.", "en": "Staircases and bridges crossing one another."}}]}, "met-337498": {"title": {"tr": "İspanyol Merdivenleri", "en": "The Spanish Steps"}, "note": {"tr": "Panini, Trinità dei Monti kilisesine çıkan yeni tamamlanmış merdiveni (1725) gezginlerle doldurur. Büyük Tur'a çıkan yabancılar için Roma'nın simgesi olmuştu.", "en": "Panini fills the recently completed staircase (1725) up to Trinità dei Monti with visitors. It had become an emblem of Rome for foreigners on the Grand Tour."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "İkiz kuleler", "en": "Twin towers"}, "text": {"tr": "Trinità dei Monti kilisesinin çan kuleleri.", "en": "The bell towers of Trinità dei Monti."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.875, "w": 1.0, "h": 0.125}, "title": {"tr": "Barcaccia", "en": "The Barcaccia"}, "text": {"tr": "Alttaki tekne biçimli çeşme.", "en": "The boat-shaped fountain at the bottom."}}, {"id": "d2", "rect": {"x": 0.25, "y": 0.625, "w": 0.625, "h": 0.25}, "title": {"tr": "Gezginler", "en": "Visitors"}, "text": {"tr": "Merdivende sohbet eden kalabalık.", "en": "A crowd chatting on the steps."}}]}, "met-362671": {"title": {"tr": "Çıkıntılı Platformdaki Tutsaklar", "en": "Prisoners on a Projecting Platform"}, "note": {"tr": "Hapishaneler dizisinin en dramatik levhalarından. Işık yukarıdan süzülürken tutsak figürleri gölgelerin içinde neredeyse kaybolur.", "en": "One of the most dramatic plates of the Prisons series. Light filters from above while the captive figures almost vanish into the shadows."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.25, "w": 0.375, "h": 0.375}, "title": {"tr": "Tutsaklar", "en": "Prisoners"}, "text": {"tr": "Platform üstünde zincirli figürler.", "en": "Chained figures on the platform."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.125, "w": 0.125, "h": 0.5}, "title": {"tr": "Asılı fener", "en": "Hanging lamp"}, "text": {"tr": "Tavandan sarkan zincir ve fener.", "en": "A chain and lamp hanging from the vault."}}]}, "met-360267": {"title": {"tr": "Hadrian Mozolesi (Castel Sant'Angelo)", "en": "The Mausoleum of Hadrian (Castel Sant'Angelo)"}, "note": {"tr": "İmparator Hadrian'ın mezarı olarak yapılan dev silindir, Orta Çağ'da papaların kalesine dönüştü. Piranesi binayı arkadan, köprü kemerleriyle birlikte gösterir; harfler açıklamaya göndermedir.", "en": "Built as Emperor Hadrian's tomb, the great drum became the popes' fortress in the Middle Ages. Piranesi shows it from behind with the bridge arches; the letters refer to the caption."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.0, "w": 0.25, "h": 0.25}, "title": {"tr": "Melek", "en": "The angel"}, "text": {"tr": "Tepedeki melek heykeli, yapıya adını verir.", "en": "The angel statue on top that gives the castle its name."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.375, "w": 0.375, "h": 0.375}, "title": {"tr": "Kemerler", "en": "Arches"}, "text": {"tr": "Sağdaki geçit kemerleri.", "en": "The passage arches on the right."}}, {"id": "d2", "rect": {"x": 0.0, "y": 0.875, "w": 1.0, "h": 0.125}, "title": {"tr": "Harfli açıklama", "en": "Lettered key"}, "text": {"tr": "Altta yapının bölümlerini anlatan metin.", "en": "The text at the bottom describing the parts."}}]}, "met-362729": {"title": {"tr": "Popolo Meydanı", "en": "The Piazza del Popolo"}, "note": {"tr": "Kuzeyden Roma'ya girenlerin ilk gördüğü meydan. Mısır'dan getirilen dikilitaşın iki yanında neredeyse ikiz iki kilise yükselir.", "en": "The first square travellers saw on entering Rome from the north. Two nearly identical churches rise on either side of the obelisk brought from Egypt."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.0, "w": 0.125, "h": 0.75}, "title": {"tr": "Dikilitaş", "en": "The obelisk"}, "text": {"tr": "Ramses II dönemine ait Flaminio dikilitaşı.", "en": "The Flaminio obelisk from the reign of Ramesses II."}}, {"id": "d1", "rect": {"x": 0.125, "y": 0.125, "w": 0.375, "h": 0.375}, "title": {"tr": "İkiz kiliseler", "en": "Twin churches"}, "text": {"tr": "Santa Maria dei Miracoli ve sağda Santa Maria in Montesanto.", "en": "Santa Maria dei Miracoli, with Santa Maria in Montesanto on the right."}}, {"id": "d2", "rect": {"x": 0.125, "y": 0.5, "w": 0.875, "h": 0.375}, "title": {"tr": "Arabalar", "en": "Carriages"}, "text": {"tr": "Meydanı geçen arabalar ve atlılar.", "en": "Carriages and riders crossing the square."}}]}, "met-438102": {"title": {"tr": "Büyük Kanal, Carità Meydanı'na Doğru", "en": "The Grand Canal, Looking Southeast"}, "note": {"tr": "Canaletto'nun İngiliz koleksiyonculara sattığı kanal görünümlerinden. Su yüzeyindeki kısa fırça vuruşları ışığı titreştirir; gondollar ölçek verir.", "en": "One of the canal views Canaletto sold to English collectors. Short strokes on the water make the light shimmer; gondolas give the scale."}, "details": [{"id": "d0", "rect": {"x": 0.75, "y": 0.125, "w": 0.125, "h": 0.5}, "title": {"tr": "Carità çan kulesi", "en": "Carità campanile"}, "text": {"tr": "Sağdaki sivri kule, 1744'te yıkıldı.", "en": "The pointed tower on the right, which collapsed in 1744."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.625, "w": 0.625, "h": 0.25}, "title": {"tr": "Gondollar", "en": "Gondolas"}, "text": {"tr": "Kanalda kürek çeken gondolcular.", "en": "Gondoliers rowing on the canal."}}]}, "met-438100": {"title": {"tr": "Büyük Kanal, Rialto'ya Doğru", "en": "The Grand Canal, Looking South toward the Rialto"}, "note": {"tr": "Önceki tabloyla eş olarak yapılmıştır. Sağda Rialto pazarının revakları, uzakta Rialto Köprüsü görünür.", "en": "Painted as a pair with the previous picture. The arcades of the Rialto market are on the right, with the Rialto Bridge in the distance."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Rialto Köprüsü", "en": "The Rialto Bridge"}, "text": {"tr": "Kanalın kıvrıldığı yerde taş köprü.", "en": "The stone bridge where the canal bends."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.375, "w": 0.375, "h": 0.375}, "title": {"tr": "Pazar binaları", "en": "Market buildings"}, "text": {"tr": "Fabbriche Nuove'nin uzun revakları.", "en": "The long arcades of the Fabbriche Nuove."}}, {"id": "d2", "rect": {"x": 0.125, "y": 0.625, "w": 0.625, "h": 0.375}, "title": {"tr": "Kayıklar", "en": "Boats"}, "text": {"tr": "Mal taşıyan kayıklar ve gondollar.", "en": "Cargo boats and gondolas."}}]}, "met-438101": {"title": {"tr": "Santa Maria Zobenigo Meydanı", "en": "Campo Santa Maria Zobenigo"}, "note": {"tr": "Kilise cephesi bir aziz yerine onu yaptıran Barbaro ailesini yüceltir: heykeller aile üyeleri, kabartmalar onların görev yaptığı şehirlerin planlarıdır.", "en": "The church façade glorifies not a saint but the Barbaro family who paid for it: the statues are family members, the reliefs plans of cities where they served."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.125, "w": 0.375, "h": 0.625}, "title": {"tr": "Barok cephe", "en": "Baroque façade"}, "text": {"tr": "Barbaro ailesinin heykelleriyle süslü cephe.", "en": "The façade adorned with statues of the Barbaro family."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.0, "w": 0.125, "h": 0.375}, "title": {"tr": "Çan kulesi", "en": "Bell tower"}, "text": {"tr": "Arkadaki tuğla kule.", "en": "The brick tower behind."}}, {"id": "d2", "rect": {"x": 0.25, "y": 0.75, "w": 0.25, "h": 0.25}, "title": {"tr": "Köpek", "en": "A dog"}, "text": {"tr": "Meydanda dolaşan küçük köpek.", "en": "A small dog wandering the square."}}]}, "met-631819": {"title": {"tr": "Genel Barış Şenliği, Pont Royal", "en": "Festival for the General Peace, Pont Royal"}, "note": {"tr": "Fransa ile İngiltere arasındaki barışı kutlayan 1801 Paris şenliği. Havai fişekler Seine'i ve Tuileries Sarayı'nı turuncuya boyar.", "en": "The 1801 Paris festival celebrating peace between France and Britain. Fireworks turn the Seine and the Tuileries Palace orange."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.125, "w": 0.5, "h": 0.25}, "title": {"tr": "Havai fişekler", "en": "Fireworks"}, "text": {"tr": "Dumanların arasında patlayan roketler.", "en": "Rockets bursting among the smoke."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.375, "w": 0.5, "h": 0.25}, "title": {"tr": "Pont Royal", "en": "The Pont Royal"}, "text": {"tr": "Seine üstündeki taş köprü.", "en": "The stone bridge over the Seine."}}, {"id": "d2", "rect": {"x": 0.5, "y": 0.75, "w": 0.5, "h": 0.125}, "title": {"tr": "Seyirciler", "en": "Spectators"}, "text": {"tr": "Kıyıda şenliği izleyen kalabalık.", "en": "The crowd watching from the bank."}}]}, "hoefnagel-flowers": {"title": {"tr": "Çiçekler, Salyangoz ve Böceklerle Natürmort", "en": "Still Life with Flowers, a Snail and Insects"}, "note": {"tr": "Hoefnagel bu küçük parşömen resmi 1589'da annesinin anısına yaptı; alttaki Latince yazı “sevgili anneme bir sevgi anıtı” anlamına gelir. Her böcek bir mücevher titizliğiyle çizilmiş.", "en": "Hoefnagel made this small painting on vellum in 1589 in memory of his mother; the Latin below reads “a monument of love to my dearest mother”. Every insect is drawn with a jeweller's care."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.875, "w": 0.5, "h": 0.125}, "title": {"tr": "Latince yazıt", "en": "Latin inscription"}, "text": {"tr": "Annesine adanan yazı ve tarih.", "en": "The dedication to his mother and the date."}}, {"id": "d1", "rect": {"x": 0.125, "y": 0.375, "w": 0.125, "h": 0.375}, "title": {"tr": "Yusufçuk", "en": "Dragonfly"}, "text": {"tr": "Vazonun solunda uzun gövdeli bir yusufçuk.", "en": "A long-bodied dragonfly to the left of the vase."}}]}, "redoute-gloriosa": {"title": {"tr": "Gloriosa superba (Tırmanıcı Zambak)", "en": "Gloriosa Superba (Climbing Lily)"}, "note": {"tr": "“Çiçeklerin Raffaello'su” diye anılan Redouté, bitkileri bilimsel doğrulukla ama büyük bir zarafetle çizdi. Bu zambak, yaprak uçlarındaki sülüklerle tırmanır.", "en": "Redouté, called the “Raphael of flowers”, drew plants with scientific accuracy and great elegance. This lily climbs with tendrils at the tips of its leaves."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.25, "w": 0.25, "h": 0.25}, "title": {"tr": "Çiçek", "en": "The flower"}, "text": {"tr": "Geriye kıvrılmış kırmızı-sarı taç yapraklar.", "en": "Red and yellow petals curling back."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.5, "w": 0.125, "h": 0.25}, "title": {"tr": "Yaprak sülüğü", "en": "Leaf tendril"}, "text": {"tr": "Yaprağın ucu bir sülük gibi kıvrılır.", "en": "The tip of the leaf curls like a tendril."}}]}, "met-395106": {"title": {"tr": "Mavi Mısır Nilüferi, “Flora Tapınağı”ndan", "en": "The Blue Egyptian Water Lily"}, "note": {"tr": "Robert Thornton'ın “Flora Tapınağı” albümü, bitkileri kendi yurtlarını hayal ettiren dramatik manzaralar içinde gösterir. Nilüfer burada palmiyeler ve kubbeli yapılarla çevrili.", "en": "Robert Thornton's “Temple of Flora” shows plants in dramatic settings that evoke their homelands. Here the water lily is surrounded by palms and domed buildings."}, "details": [{"id": "d0", "rect": {"x": 0.75, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "Palmiyeler", "en": "Palms"}, "text": {"tr": "Sağda yükselen palmiye ağaçları.", "en": "Palm trees rising on the right."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.25, "w": 0.25, "h": 0.25}, "title": {"tr": "Kubbeli yapı", "en": "Domed building"}, "text": {"tr": "Arka planda kubbeli bir bina.", "en": "A domed building in the background."}}]}, "met-762055": {"title": {"tr": "İmparatoriçe Joséphine ya da Frankfurt Gülü", "en": "‘Empress Josephine’ or Frankfort Rose"}, "note": {"tr": "Redouté'nin “Güller” albümünden. Napolyon'un eşi Joséphine'in Malmaison'daki ünlü gül bahçesi, bu çizimlere ilham kaynağı oldu.", "en": "From Redouté's “Les Roses”. Empress Josephine's famous rose garden at Malmaison inspired these plates."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.125, "w": 0.125, "h": 0.25}, "title": {"tr": "Gonca", "en": "Bud"}, "text": {"tr": "Çanak yaprakları arasından açılan bir gonca.", "en": "A bud opening between its sepals."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.5, "w": 0.375, "h": 0.375}, "title": {"tr": "Yapraklar", "en": "Leaves"}, "text": {"tr": "Tırtıklı kenarlı yapraklar tek tek çizilmiş.", "en": "Serrated leaves drawn one by one."}}]}, "met-762064": {"title": {"tr": "Ağlayan Gelin (Fritillaria imperialis)", "en": "Crown Imperial"}, "note": {"tr": "Ağlayan gelin çiçeği Anadolu ve İran'ın yabani bir bitkisidir; 16. yüzyılda İstanbul üzerinden Avrupa bahçelerine ulaştı. Redouté sarkık çanları ve yaprak tacını titizlikle çizer.", "en": "The crown imperial grows wild in Anatolia and Iran and reached European gardens via Istanbul in the 16th century. Redouté draws its hanging bells and crown of leaves with care."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.25, "w": 0.5, "h": 0.25}, "title": {"tr": "Çan çiçekler", "en": "Bells"}, "text": {"tr": "Aşağı sarkan turuncu çanlar.", "en": "Orange bells hanging downward."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.0, "w": 0.375, "h": 0.25}, "title": {"tr": "Yaprak tacı", "en": "Crown of leaves"}, "text": {"tr": "Çiçeklerin üstündeki yaprak demeti.", "en": "The tuft of leaves above the flowers."}}]}, "met-337769": {"title": {"tr": "Dört Lale", "en": "Four Tulips"}, "note": {"tr": "Jacob Marrel 1630'larda, Hollanda'da “lale çılgınlığı” yaşanırken çalıştı. En değerli laleler, bir virüsün yarattığı alevli çizgileri taşıyanlardı; altlarındaki yazılar türlerin adıdır.", "en": "Jacob Marrel worked in the 1630s, during Dutch “tulip mania”. The most prized tulips had flame-like stripes caused by a virus; the inscriptions below name the varieties."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.5, "w": 0.25, "h": 0.125}, "title": {"tr": "Kelebek", "en": "Butterfly"}, "text": {"tr": "Lalelerin arasında küçük bir kelebek.", "en": "A small butterfly among the tulips."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.25, "w": 0.375, "h": 0.25}, "title": {"tr": "Alevli taç", "en": "Flamed petals"}, "text": {"tr": "Kırmızı-beyaz çizgili taç yapraklar.", "en": "Red-and-white striped petals."}}]}, "met-395105": {"title": {"tr": "Sümbüller, “Flora Tapınağı”ndan", "en": "Hyacinths"}, "note": {"tr": "Thornton'ın albümünden bir sayfa daha. Beyaz ve koyu mavi sümbüller, alçak bir ufkun önünde anıtsal bir ölçekle yükselir.", "en": "Another plate from Thornton's album. White and deep blue hyacinths rise to a monumental scale before a low horizon."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.25, "w": 0.25, "h": 0.375}, "title": {"tr": "Koyu mavi sümbül", "en": "Deep blue hyacinth"}, "text": {"tr": "Sağdaki koyu mavi çiçek salkımı.", "en": "The deep blue cluster on the right."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.625, "w": 0.25, "h": 0.125}, "title": {"tr": "Uzak manzara", "en": "Distant view"}, "text": {"tr": "Ufukta küçük bir kasaba.", "en": "A small town on the horizon."}}]}, "met-399922": {"title": {"tr": "Kapari, Karaçalı ve Böcek Etüdü", "en": "Study of Capers, Gorse, and a Beetle"}, "note": {"tr": "Maria Sibylla Merian bitkileri ve böcekleri birlikte gözlemleyen öncü bir doğa bilimci ve sanatçıydı. Parşömen üzerindeki bu etüt, onun bilimsel merakını yansıtır.", "en": "Maria Sibylla Merian was a pioneering naturalist-artist who observed plants and insects together. This study on vellum reflects her scientific curiosity."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.25, "w": 0.125, "h": 0.125}, "title": {"tr": "Böcek", "en": "Beetle"}, "text": {"tr": "Kapari dalının üstünde kırmızı bir böcek.", "en": "A red beetle on the caper stem."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.25, "w": 0.25, "h": 0.5}, "title": {"tr": "Karaçalı", "en": "Gorse"}, "text": {"tr": "Sağdaki sarı çiçekli dal.", "en": "The yellow-flowered branch on the right."}}]}, "met-364533": {"title": {"tr": "Çiçek Etütleri Sayfası", "en": "A Sheet of Studies of Flowers"}, "note": {"tr": "Jacques Le Moyne de Morgues 16. yüzyılın en yetenekli botanik ressamlarındandı. Gül, hercai menekşe ve bezelye çiçekleri tek bir sayfada bir araya gelir.", "en": "Jacques Le Moyne de Morgues was among the finest botanical painters of the 16th century. Rose, heartsease and pea flowers share a single sheet."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.0, "w": 0.25, "h": 0.25}, "title": {"tr": "Gül", "en": "Rose"}, "text": {"tr": "Sol üstte pembe bir gül.", "en": "A pink rose at top left."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.625, "w": 0.125, "h": 0.125}, "title": {"tr": "Hercai menekşe", "en": "Heartsease"}, "text": {"tr": "Sağ altta küçük bir hercai menekşe.", "en": "A small heartsease at lower right."}}]}, "met-366733": {"title": {"tr": "Üç Açılış Evresinde Gelincik", "en": "A Poppy in Three Stages of Flowering"}, "note": {"tr": "Johanna Helena Herolt, Maria Sibylla Merian'ın kızıydı ve annesi gibi bitki ile böceği birlikte resmetti. Tomurcuk, çiçek ve tohum kapsülü yan yana; tırtıl ve kelebek de öyle.", "en": "Johanna Helena Herolt was Maria Sibylla Merian's daughter and, like her mother, painted plants and insects together. Bud, flower and seed head appear side by side, as do caterpillar and butterfly."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.0, "w": 0.25, "h": 0.125}, "title": {"tr": "Kelebek", "en": "Butterfly"}, "text": {"tr": "Tepede kanatlarını açmış bir kelebek.", "en": "A butterfly with open wings at the top."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.625, "w": 0.125, "h": 0.125}, "title": {"tr": "Tırtıl", "en": "Caterpillar"}, "text": {"tr": "Yaprakların arasında bir tırtıl.", "en": "A caterpillar among the leaves."}}]}, "met-385749": {"title": {"tr": "Kanatlı Çarkıfelek (Passiflora alata)", "en": "Winged Passionflower"}, "note": {"tr": "Sydenham Edwards 1799'da parşömen üzerine guaşla çizdi. Çarkıfeleğin karmaşık iç halkası ve spiral sülükleri büyüleyici bir ayrıntı zenginliği sunar.", "en": "Sydenham Edwards painted this in gouache on vellum in 1799. The passionflower's intricate corona and spiral tendrils offer a wealth of detail."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.375, "w": 0.25, "h": 0.125}, "title": {"tr": "Çiçeğin merkezi", "en": "The corona"}, "text": {"tr": "İnce iplik gibi taç halkası.", "en": "The thread-like corona at the flower's centre."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.25, "w": 0.25, "h": 0.125}, "title": {"tr": "Spiral sülük", "en": "Spiral tendril"}, "text": {"tr": "Sağda yay gibi kıvrılmış bir sülük.", "en": "A spring-like coiled tendril on the right."}}]}, "met-334930": {"title": {"tr": "Meyve, Böcek ve Deniz Kabuğu Etütleri", "en": "Studies of Fruits, Insects and Shells"}, "note": {"tr": "Georg Flegel'in parşömen üzerine suluboya etütleri, natürmortlarında kullandığı nesnelerin bir tür kataloğudur. Çilek, bezelye kabuğu ve güveler gerçek boyutlarına yakın çizilmiş.", "en": "Georg Flegel's watercolour studies on parchment are a kind of catalogue of the objects in his still lifes. Strawberry, pea pod and moths are drawn close to life size."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.375, "w": 0.25, "h": 0.375}, "title": {"tr": "Çilek", "en": "Strawberry"}, "text": {"tr": "Tohumları tek tek işlenmiş iri bir çilek.", "en": "A large strawberry with each seed rendered."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.0, "w": 0.375, "h": 0.375}, "title": {"tr": "Güve", "en": "Moth"}, "text": {"tr": "Kırmızı arka kanatlı büyük bir güve.", "en": "A large moth with red hindwings."}}]}, "met-437881": {"title": {"tr": "Su Testili Genç Kadın", "en": "Young Woman with a Water Pitcher"}, "note": {"tr": "Vermeer'in sessiz iç mekânlarının en saf örneklerinden. Pencereden giren serin ışık; beyaz başlığı, gümüş leğeni ve masa örtüsünün koyu kırmızısını aynı anda okşar.", "en": "One of the purest of Vermeer's quiet interiors. Cool light from the window touches the white headdress, the silver basin and the deep red of the table carpet all at once."}, "details": [{"id": "d0", "rect": {"x": 0.75, "y": 0.0, "w": 0.25, "h": 0.375}, "title": {"tr": "Duvardaki harita", "en": "Map on the wall"}, "text": {"tr": "Arka duvarda Vermeer'in sık kullandığı harita motiflerinden biri asılı.", "en": "One of the maps Vermeer often used hangs on the back wall."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.5, "w": 0.25, "h": 0.25}, "title": {"tr": "Testi ve leğen", "en": "Pitcher and basin"}, "text": {"tr": "Gümüş testi ve leğende pencerenin ışığı yansır.", "en": "The window light is reflected in the silver pitcher and basin."}}]}, "met-437549": {"title": {"tr": "Buğday Tarlaları", "en": "Wheat Fields"}, "note": {"tr": "Ruisdael tablonun üçte ikisini gökyüzüne ayırır. Hollanda düzlüğünde bulutlar, manzaranın asıl kahramanıdır; yol bakışı derinliğe doğru çeker.", "en": "Ruisdael gives two thirds of the canvas to the sky. Over the flat Dutch land the clouds are the real protagonists; the road draws the eye into depth."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.75, "w": 0.125, "h": 0.125}, "title": {"tr": "Yürüyen figür", "en": "Walking figure"}, "text": {"tr": "Yolda tek başına yürüyen küçük bir insan, manzaranın ölçeğini verir.", "en": "A tiny lone walker on the road gives the landscape its scale."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.375, "w": 0.25, "h": 0.375}, "title": {"tr": "Yalnız ağaç", "en": "The lone tree"}, "text": {"tr": "Sağdaki ağaç, tarlaların ışığına karşı koyu bir siluet oluşturur.", "en": "The tree on the right forms a dark silhouette against the bright fields."}}]}, "met-437749": {"title": {"tr": "Terasta Neşeli Topluluk", "en": "Merry Company on a Terrace"}, "note": {"tr": "Jan Steen'in kalabalık, gürültülü sahneleri bir ahlak dersi gibi okunabilir ama önce eğlendirir. Her köşede küçük bir olay yaşanır.", "en": "Jan Steen's crowded, noisy scenes can be read as moral lessons, but first they entertain. A small event unfolds in every corner."}, "details": [{"id": "d0", "rect": {"x": 0.75, "y": 0.0, "w": 0.25, "h": 0.25}, "title": {"tr": "Çardaktaki adam", "en": "Man in the arbour"}, "text": {"tr": "Sağ üstte bir adam çardağa tırmanmış, topluluğa sesleniyor.", "en": "Top right, a man has climbed into the arbour and calls to the company."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.75, "w": 0.125, "h": 0.25}, "title": {"tr": "Devrik testi", "en": "Overturned jug"}, "text": {"tr": "Yerde devrilmiş bir testi, eğlencenin dağınıklığını anlatır.", "en": "A jug lying on the floor tells of the party's disorder."}}]}, "met-437879": {"title": {"tr": "Genç Bir Kadın Etüdü", "en": "Study of a Young Woman"}, "note": {"tr": "Belirli birinin portresi değil, Hollandalıların “tronie” dediği bir karakter etüdü. Koyu fonda yüz, ışığı içinden yayıyormuş gibi görünür.", "en": "Not a portrait of a specific sitter but a character study, a “tronie”. Against the dark ground the face seems to glow from within."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.375, "w": 0.25, "h": 0.125}, "title": {"tr": "Bakış", "en": "The gaze"}, "text": {"tr": "Omzunun üzerinden izleyiciye dönen geniş, sakin gözler.", "en": "Wide, calm eyes turning to the viewer over her shoulder."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.625, "w": 0.375, "h": 0.375}, "title": {"tr": "Şal", "en": "The shawl"}, "text": {"tr": "Mavi-gri şalın kıvrımları birkaç geniş fırça darbesiyle kurulmuş.", "en": "The folds of the blue-grey shawl are built with a few broad strokes."}}]}, "met-437878": {"title": {"tr": "Uyuyan Hizmetçi", "en": "A Maid Asleep"}, "note": {"tr": "Vermeer'in erken dönem iç mekânlarından. Teknik incelemeler, açık kapıda başlangıçta bir köpek ve arka odada bir adam bulunduğunu, ressamın bunları sonradan sildiğini gösterdi.", "en": "An early Vermeer interior. Technical studies showed that a dog in the doorway and a man in the back room were originally painted and later removed."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.125, "w": 0.25, "h": 0.375}, "title": {"tr": "Aralık kapı", "en": "The open door"}, "text": {"tr": "Kapıdan görünen ikinci oda, sahneye derinlik ve gizem katar.", "en": "The second room seen through the door adds depth and mystery."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Masadaki natürmort", "en": "Still life on the table"}, "text": {"tr": "Halı örtülü masada bir testi ve meyve tabağı duruyor.", "en": "A jug and a dish of fruit sit on the carpet-covered table."}}]}, "met-437880": {"title": {"tr": "Lavtalı Genç Kadın", "en": "Young Woman with a Lute"}, "note": {"tr": "Kadın lavtasını akort ederken pencereden dışarı bakıyor; belki birini bekliyor. Duvardaki büyük Avrupa haritası, dışarıdaki dünyayı odaya taşır.", "en": "She tunes her lute while gazing out of the window, perhaps waiting for someone. The large map of Europe on the wall brings the outside world into the room."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.0, "w": 0.5, "h": 0.5}, "title": {"tr": "Avrupa haritası", "en": "Map of Europe"}, "text": {"tr": "Arka duvarı kaplayan harita, Vermeer'in en sevdiği motiflerden.", "en": "The map covering the back wall is one of Vermeer's favourite motifs."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.375, "w": 0.375, "h": 0.25}, "title": {"tr": "Lavta", "en": "The lute"}, "text": {"tr": "Işık, çalgının sapı ve kadının elleri üzerinde toplanır.", "en": "Light gathers on the instrument's neck and her hands."}}]}, "met-459086": {"title": {"tr": "Zarif Bir Odada Boş Vakit", "en": "Leisure Time in an Elegant Setting"}, "note": {"tr": "De Hooch varlıklı bir Hollanda evinin içini gösterir: yaldızlı deri duvarlar, mermer zemin, şarap ve sohbet. Işık, odalar arasında katman katman ilerler.", "en": "De Hooch shows the inside of a wealthy Dutch home: gilt-leather walls, a marble floor, wine and conversation. Light moves in layers from room to room."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.0, "w": 0.375, "h": 0.375}, "title": {"tr": "Yaldızlı deri", "en": "Gilt leather"}, "text": {"tr": "Duvarları kaplayan kabartmalı deri, dönemin lüks bir süslemesiydi.", "en": "The embossed leather covering the walls was a luxury of the period."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.75, "w": 0.5, "h": 0.25}, "title": {"tr": "Dama zemin", "en": "Checkered floor"}, "text": {"tr": "Siyah-beyaz zemin taşları perspektifi açıkça kurar.", "en": "The black-and-white floor tiles lay out the perspective clearly."}}]}, "met-437397": {"title": {"tr": "Otoportre", "en": "Self-Portrait"}, "note": {"tr": "Rembrandt 1660'ta, elli dört yaşındayken. Hayatı boyunca kendini onlarca kez resmetti; bu tabloda yaşlanmayı hiç saklamadan, açık sözlülükle gösterir.", "en": "Rembrandt in 1660, aged fifty-four. He painted himself dozens of times; here he shows ageing frankly, without disguise."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.25, "w": 0.25, "h": 0.25}, "title": {"tr": "Gözler", "en": "The eyes"}, "text": {"tr": "Hafifçe yorgun gözler, tüm yüzün ifadesini taşır.", "en": "Slightly weary eyes carry the expression of the whole face."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.125, "w": 0.5, "h": 0.25}, "title": {"tr": "Bere", "en": "The beret"}, "text": {"tr": "Koyu bere, yüzün ışığını çerçeveleyen bir gölge gibi durur.", "en": "The dark beret sits like a shadow framing the light of the face."}}]}, "met-436622": {"title": {"tr": "Karnaval Eğlencesi", "en": "Merrymakers at Shrovetide"}, "note": {"tr": "Frans Hals'ın erken dönem başyapıtı. Perhiz öncesi karnavalın kostümlü figürleri tabloyu kenarına kadar doldurur; masa ise yiyeceklerle taşar.", "en": "An early masterpiece by Frans Hals. Costumed carnival figures fill the canvas to its edges before Lent, and the table overflows with food."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Dantel yaka", "en": "Lace collar"}, "text": {"tr": "Ortadaki figürün geniş dantel yakası hızlı fırça darbeleriyle çizilmiş.", "en": "The central figure's broad lace collar is drawn in quick strokes."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.75, "w": 0.375, "h": 0.25}, "title": {"tr": "Masadaki yiyecekler", "en": "Food on the table"}, "text": {"tr": "Sosis, ekmek ve testi; karnavalın bolluğunu anlatan küçük bir natürmort.", "en": "Sausage, bread and a jug: a small still life of carnival plenty."}}]}, "met-436616": {"title": {"tr": "Handa Genç Adam ve Kadın", "en": "Young Man and Woman in an Inn"}, "note": {"tr": "“Yonker Ramp ve Sevgilisi” adıyla da bilinir. Kadehini kaldıran gencin kahkahası, Hals'ın anı yakalayan çevik fırçasıyla neredeyse duyulur.", "en": "Also known as “Yonker Ramp and His Sweetheart”. The laugh of the young man raising his glass is almost audible through Hals's quick brush."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.0, "w": 0.125, "h": 0.25}, "title": {"tr": "Kaldırılan kadeh", "en": "Raised glass"}, "text": {"tr": "Sol üst köşede kadeh havaya kaldırılmış.", "en": "In the top left corner a glass is raised high."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Gülen kadın", "en": "The smiling woman"}, "text": {"tr": "Gencin omzuna yaslanan kadın da gülümsüyor.", "en": "The woman leaning on his shoulder smiles too."}}]}, "met-436677": {"title": {"tr": "Hanımefendiye Ödeme", "en": "Paying the Hostess"}, "note": {"tr": "Bir handa şık giyimli bir müşteri hesabı ödüyor. De Hooch'un sevdiği gibi arka planda açık bir kapı, sahneyi başka bir mekâna açar.", "en": "In an inn, a well-dressed guest settles his bill. As de Hooch liked, an open door in the background opens the scene onto another space."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.5, "w": 0.25, "h": 0.375}, "title": {"tr": "Hancı kadın", "en": "The hostess"}, "text": {"tr": "Kadın elini uzatmış, ödemeyi bekliyor.", "en": "The woman holds out her hand, waiting for payment."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.25, "w": 0.25, "h": 0.375}, "title": {"tr": "Arkadaki oda", "en": "The room beyond"}, "text": {"tr": "Işıklı arka odada başka figürler seçilir.", "en": "Other figures can be made out in the bright room beyond."}}]}, "met-437877": {"title": {"tr": "Katolik İnancın Alegorisi", "en": "Allegory of the Catholic Faith"}, "note": {"tr": "Vermeer'in geç dönem eseri ve nadir alegorilerinden biri. Kadın figürü İnanç'ı temsil eder; çevresindeki her nesnenin bir sembol anlamı vardır.", "en": "A late work and one of Vermeer's rare allegories. The woman personifies Faith, and every object around her carries symbolic meaning."}, "details": [{"id": "d0", "rect": {"x": 0.75, "y": 0.25, "w": 0.125, "h": 0.125}, "title": {"tr": "Cam küre", "en": "Glass sphere"}, "text": {"tr": "Tavandan sarkan cam küre, sonsuzluğu ve inancı simgeler.", "en": "The glass sphere hanging from the ceiling symbolises infinity and faith."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.875, "w": 0.25, "h": 0.125}, "title": {"tr": "Taş ve yılan", "en": "Stone and serpent"}, "text": {"tr": "Zeminde bir köşe taşının altında ezilmiş yılan görülür.", "en": "On the floor a serpent lies crushed beneath a cornerstone."}}]}, "vangogh-cypresses": {"title": {"tr": "Selvili Buğday Tarlası", "en": "Wheat Field with Cypresses"}, "note": {"tr": "1889'da Saint-Rémy'de yapıldı. Van Gogh kardeşi Theo'ya selvilerin çizgi ve oranlarının bir Mısır dikilitaşı kadar güzel olduğunu yazmıştı. Gökyüzü, buğday ve ağaç aynı kıvrak fırça ritmiyle titreşir.", "en": "Painted at Saint-Rémy in 1889. Van Gogh wrote to his brother Theo that cypresses were as beautiful in line and proportion as an Egyptian obelisk. Sky, wheat and tree vibrate with the same swirling brushwork."}, "details": [{"id": "d0", "rect": {"x": 0.75, "y": 0.125, "w": 0.25, "h": 0.5}, "title": {"tr": "Selvi", "en": "The cypress"}, "text": {"tr": "Koyu yeşil selvi, alevi andıran bir biçimle göğe yükselir.", "en": "The dark green cypress rises to the sky like a flame."}}, {"id": "d1", "rect": {"x": 0.125, "y": 0.75, "w": 0.5, "h": 0.25}, "title": {"tr": "Buğday", "en": "The wheat"}, "text": {"tr": "Buğday başakları kalın, kıvrımlı boya darbeleriyle dalgalanır.", "en": "The wheat ripples in thick, curling strokes of paint."}}]}, "met-436528": {"title": {"tr": "Süsenler", "en": "Irises"}, "note": {"tr": "Van Gogh, Saint-Rémy'den ayrılmadan hemen önce, Mayıs 1890'da yaptı. Çiçekler aslında morumsu, fon pembemsiydi; kırmızı pigment zamanla solduğu için bugün mavi ve beyaz görünürler.", "en": "Painted in May 1890, just before Van Gogh left Saint-Rémy. The flowers were originally purplish and the background pinkish; the red pigment has faded, so today they look blue and white."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.625, "w": 0.25, "h": 0.375}, "title": {"tr": "Vazo", "en": "The vase"}, "text": {"tr": "Sade beyaz vazo, taşan buketin ağırlığını taşır.", "en": "A plain white vase carries the weight of the overflowing bouquet."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.0, "w": 0.25, "h": 0.25}, "title": {"tr": "Tepedeki çiçek", "en": "Top bloom"}, "text": {"tr": "En üstteki süsen, buketin dışına doğru uzanır.", "en": "The highest iris reaches out beyond the bouquet."}}]}, "met-437654": {"title": {"tr": "Sirk Gösterisi (Parade de cirque)", "en": "Circus Sideshow"}, "note": {"tr": "Seurat'nın ilk gece sahnesi. Sirkin önünde, seyirci çekmek için yapılan ücretsiz ön gösteriyi gaz lambalarının soluk ışığında, binlerce küçük renk noktasıyla kurar.", "en": "Seurat's first night scene. In the pale light of gas lamps he builds the free sideshow staged outside the circus to draw in an audience, from thousands of tiny dots of colour."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.25, "w": 0.125, "h": 0.375}, "title": {"tr": "Trombon çalan", "en": "Trombonist"}, "text": {"tr": "Ortadaki müzisyen, sahnenin donuk simetrisinin merkezidir.", "en": "The musician at the centre anchors the scene's still symmetry."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.125, "w": 0.375, "h": 0.125}, "title": {"tr": "Gaz lambaları", "en": "Gas lamps"}, "text": {"tr": "Üst sıradaki lambalar, noktalarla çizilmiş hareli ışık halkalarıdır.", "en": "The lamps along the top are halos of light built from dots."}}]}, "met-459112": {"title": {"tr": "Piyano Başında İki Genç Kız", "en": "Two Young Girls at the Piano"}, "note": {"tr": "Renoir bu konuyu birkaç kez resmetti; sıcak tonlar ve yumuşak fırça, evdeki sakin bir öğleden sonrayı anlatır.", "en": "Renoir painted this subject several times; warm tones and a soft brush evoke a quiet afternoon at home."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.25, "w": 0.25, "h": 0.375}, "title": {"tr": "Nota defteri", "en": "The sheet music"}, "text": {"tr": "Kızların birlikte baktığı notalar, sahnenin odak noktasıdır.", "en": "The music the girls look at together is the scene's focus."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "Çiçekli vazo", "en": "Vase of flowers"}, "text": {"tr": "Piyanonun üstünde küçük bir buket.", "en": "A small bouquet on top of the piano."}}]}, "met-437430": {"title": {"tr": "Deniz Kıyısında", "en": "By the Seashore"}, "note": {"tr": "Hasır bir koltukta oturan genç kadın, arkasında kayalıklar ve deniz. Renoir yüzü özenle, manzarayı ise hızlı ve titrek fırça darbeleriyle boyar.", "en": "A young woman sits in a wicker chair with cliffs and sea behind her. Renoir paints the face with care and the landscape with quick, shimmering strokes."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.5, "w": 0.625, "h": 0.375}, "title": {"tr": "Hasır koltuk", "en": "Wicker chair"}, "text": {"tr": "Koltuğun örgüsü birkaç sarı fırça çizgisiyle kurulmuş.", "en": "The chair's weave is built from a few yellow strokes."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.125, "w": 0.5, "h": 0.25}, "title": {"tr": "Kayalıklar ve deniz", "en": "Cliffs and sea"}, "text": {"tr": "Arka plandaki kıyı, mavi ve yeşil lekelerle çözülür.", "en": "The coastline behind dissolves into patches of blue and green."}}]}, "met-435868": {"title": {"tr": "Kâğıt Oynayanlar", "en": "The Card Players"}, "note": {"tr": "Cézanne, Provence'taki köylüleri model alarak bu konunun beş çeşitlemesini yaptı. Figürler bir heykel gibi ağır ve sessiz; oyunun gerilimi neredeyse hiç kıpırdamayan ellerdedir.", "en": "Cézanne painted five versions of this subject using Provençal farmhands as models. The figures are heavy and silent like sculpture; the game's tension lies in hands that barely move."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.125, "w": 0.25, "h": 0.125}, "title": {"tr": "Duvardaki pipolar", "en": "Pipes on the wall"}, "text": {"tr": "Arka duvarda asılı pipolar, kahvehanenin gündelik havasını verir.", "en": "Pipes hanging on the back wall give the café its everyday air."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.0, "w": 0.25, "h": 0.375}, "title": {"tr": "İzleyen adam", "en": "The onlooker"}, "text": {"tr": "Ayakta duran adam oyunu sessizce izliyor.", "en": "The standing man watches the game in silence."}}]}, "met-437299": {"title": {"tr": "Jalais Tepesi, Pontoise", "en": "Jalais Hill, Pontoise"}, "note": {"tr": "Pissarro'nun izlenimcilik öncesi döneminden; 1868 Salonu'nda sergilendi ve Émile Zola tarafından övüldü. Köy, tepe ve gökyüzü sağlam, düzenli kütlelerle kurulur.", "en": "From Pissarro's pre-Impressionist years; shown at the 1868 Salon and praised by Émile Zola. Village, hill and sky are built from solid, ordered masses."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Köy evleri", "en": "Village houses"}, "text": {"tr": "Beyaz duvarlı evler, yeşilin içinde parlak lekeler oluşturur.", "en": "White-walled houses make bright patches in the green."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.625, "w": 0.125, "h": 0.125}, "title": {"tr": "Yoldaki kadın", "en": "Woman on the path"}, "text": {"tr": "Patikada yürüyen küçük bir figür.", "en": "A small figure walking along the path."}}]}, "met-436532": {"title": {"tr": "Hasır Şapkalı Otoportre", "en": "Self-Portrait with a Straw Hat"}, "note": {"tr": "Van Gogh 1887'de Paris'te, model tutacak parası olmadığı için kendini çok sık resmetti. Bu tuvalin arka yüzünde daha önceki bir resmi, “Patates Soyan Kadın” bulunur.", "en": "In Paris in 1887 Van Gogh, unable to pay models, often painted himself. The back of this canvas carries an earlier picture, “The Potato Peeler”."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.25, "w": 0.25, "h": 0.25}, "title": {"tr": "Gözler", "en": "The eyes"}, "text": {"tr": "Yeşil ve mavi tonlarla çizilmiş delici bir bakış.", "en": "A piercing gaze drawn in greens and blues."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.5, "w": 0.25, "h": 0.5}, "title": {"tr": "Fırça darbeleri", "en": "Brushstrokes"}, "text": {"tr": "Arka planda kısa, yönlü fırça vuruşları bir doku oluşturur.", "en": "Short, directional strokes create a texture in the background."}}]}, "met-437658": {"title": {"tr": "“La Grande Jatte'da Bir Pazar” İçin Etüt", "en": "Study for “A Sunday on La Grande Jatte”"}, "note": {"tr": "Seurat'nın ünlü büyük tablosu için yaptığı son ve en kapsamlı yağlıboya etüdü. Paris'in yakınındaki adada pazar gününü geçiren insanlar, ışık ve gölgenin geometrisiyle yerleştirilmiş.", "en": "Seurat's last and most complete oil study for his famous large painting. People spending a Sunday on the island near Paris are placed by a geometry of light and shadow."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.125, "w": 0.125, "h": 0.25}, "title": {"tr": "Yelkenli", "en": "Sailboat"}, "text": {"tr": "Seine Nehri'nde küçük bir yelkenli.", "en": "A small sailboat on the Seine."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.125, "w": 0.125, "h": 0.125}, "title": {"tr": "Kırmızı şemsiye", "en": "Red parasol"}, "text": {"tr": "Kalabalığın arasında bir güneş şemsiyesinin kırmızısı parlar.", "en": "The red of a parasol shines among the crowd."}}]}, "met-438821": {"title": {"tr": "Ia Orana Maria (Selam Sana Meryem)", "en": "Ia Orana Maria (Hail Mary)"}, "note": {"tr": "Gauguin'in Tahiti'de yaptığı ilk büyük tablo. Hıristiyan Meryem ve Çocuk İsa sahnesini, hale taşıyan Tahitili bir anne ve oğluyla yeniden kurar.", "en": "Gauguin's first major painting in Tahiti. He recasts the Christian Virgin and Child as a Tahitian mother and son crowned with haloes."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.75, "w": 0.375, "h": 0.25}, "title": {"tr": "Meyve sunusu", "en": "Fruit offering"}, "text": {"tr": "Ön plandaki muzlar ve meyveler, bir sunak gibi dizilmiş.", "en": "Bananas and fruit in the foreground are laid out like an altar."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.875, "w": 0.375, "h": 0.125}, "title": {"tr": "Başlık", "en": "The title"}, "text": {"tr": "Tablonun adı, sol alt köşeye Tahiti dilinde yazılmış.", "en": "The title is written in Tahitian in the lower left corner."}}]}, "met-436947": {"title": {"tr": "Kayıkta", "en": "Boating"}, "note": {"tr": "Manet bu tabloyu 1874 yazında, Monet ile birlikte çalıştığı Argenteuil'de yaptı. Ufuk çizgisi yok; su, bütün arka planı kaplayan düz bir mavi yüzeydir.", "en": "Manet painted this in the summer of 1874 at Argenteuil, where he worked alongside Monet. There is no horizon; the water is a flat blue surface filling the background."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.125, "w": 0.375, "h": 0.25}, "title": {"tr": "Hasır şapka", "en": "Straw hat"}, "text": {"tr": "Kürekçinin şapkası beyaz giysisiyle birlikte ışığı toplar.", "en": "The boater's hat and white clothes gather the light."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.25, "w": 0.25, "h": 0.375}, "title": {"tr": "Tül", "en": "The veil"}, "text": {"tr": "Kadının şapkasından inen tül, birkaç beyaz fırça darbesidir.", "en": "The veil falling from her hat is a few strokes of white."}}]}, "met-436140": {"title": {"tr": "Pembe ve Yeşilli Dansçılar", "en": "Dancers, Pink and Green"}, "note": {"tr": "Degas balerinleri sahnede değil, sahne arkasında, kostümlerini düzeltirken gösterir. Dekor panoları arasından bakıyormuşuz gibi bir kesit sunar.", "en": "Degas shows the dancers not on stage but in the wings, adjusting their costumes. We seem to look between the stage flats."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.25, "w": 0.25, "h": 0.25}, "title": {"tr": "Askısını düzelten dansçı", "en": "Adjusting a strap"}, "text": {"tr": "Bir balerin omzundaki askıyı düzeltiyor.", "en": "A dancer fixes the strap on her shoulder."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.5, "w": 0.5, "h": 0.375}, "title": {"tr": "Yeşil etekler", "en": "Green skirts"}, "text": {"tr": "Tütüler parlak yeşil, hızlı pastel benzeri darbelerle boyanmış.", "en": "The tutus are painted in bright green, quick pastel-like strokes."}}]}, "met-435877": {"title": {"tr": "Sainte-Victoire Dağı ve Arc Vadisi Viyadüğü", "en": "Mont Sainte-Victoire and the Viaduct"}, "note": {"tr": "Cézanne doğduğu Aix-en-Provence yakınlarındaki bu dağı onlarca kez resmetti. Önde çam ağacı, ortada vadi ve demiryolu viyadüğü, arkada dağ; manzara katmanlar hâlinde dizilir.", "en": "Cézanne painted this mountain near his native Aix-en-Provence dozens of times. A pine in front, the valley and railway viaduct in the middle, the mountain behind: the landscape is stacked in layers."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.375, "w": 0.375, "h": 0.125}, "title": {"tr": "Viyadük", "en": "The viaduct"}, "text": {"tr": "Vadinin ortasından geçen kemerli demiryolu köprüsü.", "en": "The arched railway bridge crossing the middle of the valley."}}, {"id": "d1", "rect": {"x": 0.125, "y": 0.125, "w": 0.375, "h": 0.25}, "title": {"tr": "Sainte-Victoire", "en": "Sainte-Victoire"}, "text": {"tr": "Dağın silueti, mavi-mor tonlarla ufukta yükselir.", "en": "The mountain's silhouette rises on the horizon in blue-violet tones."}}]}, "met-452111": {"title": {"tr": "Sede Şenliği", "en": "The Feast of Sada"}, "note": {"tr": "Şah Tahmasp'ın Şehnamesi, İran resim sanatının doruk noktası sayılır. Bu sayfada Şah Huşeng ateşi keşfeder ve bu buluşu Sede şenliğiyle kutlar.", "en": "Shah Tahmasp's Shahnama is counted the summit of Persian painting. On this page King Hushang discovers fire and celebrates the discovery with the feast of Sada."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.25, "w": 0.25, "h": 0.25}, "title": {"tr": "Huşeng", "en": "Hushang"}, "text": {"tr": "Ortada tahtında oturan Şah Huşeng.", "en": "King Hushang seated at the centre."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.5, "w": 0.25, "h": 0.125}, "title": {"tr": "Ateş", "en": "The fire"}, "text": {"tr": "Ortadaki ateş, keşfin simgesi.", "en": "The fire at the centre, symbol of the discovery."}}, {"id": "d2", "rect": {"x": 0.125, "y": 0.625, "w": 0.625, "h": 0.25}, "title": {"tr": "Şiir", "en": "The verses"}, "text": {"tr": "Firdevsi'nin dizeleri dört sütunda.", "en": "Firdausi's verses in four columns."}}]}, "met-449533": {"title": {"tr": "Kanuni Sultan Süleyman'ın Tuğrası", "en": "Tughra of Sultan Süleiman the Magnificent"}, "note": {"tr": "Tuğra, padişahın resmî imzasıdır ve fermanların başına çekilirdi. Bu süslü örnekte kıvrımların içi lacivert ve altın renkli çiçek motifleriyle doldurulmuş.", "en": "The tughra was the sultan's official monogram, drawn at the head of imperial decrees. In this ornate example the loops are filled with blue and gold floral motifs."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.0, "w": 0.25, "h": 0.625}, "title": {"tr": "Tuğ'lar", "en": "The shafts"}, "text": {"tr": "Yükselen üç dikey çizgi, “tuğ” denen elif harfleri.", "en": "The three rising vertical strokes, the tall alifs."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.25, "w": 0.625, "h": 0.5}, "title": {"tr": "Beyzeler", "en": "The loops"}, "text": {"tr": "İç içe geçmiş büyük kıvrımlar ve içlerindeki çiçek bezemesi.", "en": "The great interlaced loops and their floral decoration."}}, {"id": "d2", "rect": {"x": 0.0, "y": 0.75, "w": 0.5, "h": 0.25}, "title": {"tr": "Ferman metni", "en": "The decree"}, "text": {"tr": "Altta başlayan fermanın ilk satırı.", "en": "The first line of the decree beneath."}}]}, "met-445297": {"title": {"tr": "“Lotto” Halısı", "en": "'Lotto' Carpet"}, "note": {"tr": "Uşak bölgesinde dokunan bu halılar, Venedikli ressam Lorenzo Lotto'nun tablolarında göründüğü için onun adıyla anılır. Kırmızı zemin üstünde sarı arabesk ağ.", "en": "Woven in the Ushak region, these carpets are named after the Venetian painter Lorenzo Lotto because they appear in his pictures. A yellow arabesque lattice on a red ground."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.125, "w": 0.625, "h": 0.75}, "title": {"tr": "Arabesk ağ", "en": "Arabesque lattice"}, "text": {"tr": "Sarı yapraklı motiflerin oluşturduğu sonsuz örüntü.", "en": "An endless pattern of yellow leaf forms."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.0, "w": 1.0, "h": 0.125}, "title": {"tr": "Bordür", "en": "Border"}, "text": {"tr": "Kenardaki kufi yazıdan türeyen bordür.", "en": "The border derived from Kufic script."}}]}, "met-452112": {"title": {"tr": "Tahmuras Devleri Yeniyor", "en": "Tahmuras Defeats the Divs"}, "note": {"tr": "Şehname'nin efsanevi şahı Tahmuras, kötülük yaratıkları devleri yener. Yenilen devler, karşılığında ona yazıyı öğretir.", "en": "Tahmuras, the legendary king of the Shahnama, defeats the demons called divs. In return for their lives they teach him the art of writing."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.375, "w": 0.25, "h": 0.125}, "title": {"tr": "Tahmuras", "en": "Tahmuras"}, "text": {"tr": "Atının üstünde topuzunu kaldıran şah.", "en": "The king on horseback raising his mace."}}, {"id": "d1", "rect": {"x": 0.125, "y": 0.5, "w": 0.375, "h": 0.125}, "title": {"tr": "Devler", "en": "The divs"}, "text": {"tr": "Benekli ve boynuzlu devler.", "en": "The spotted, horned demons."}}]}, "met-446595": {"title": {"tr": "Ferhat Şirin İçin Süt Kanalı Kazıyor", "en": "Farhad Carves a Milk Channel for Shirin"}, "note": {"tr": "Nizami'nin Hüsrev ü Şirin'inde taş ustası Ferhat, Şirin'e olan aşkıyla dağı oyarak süt akacak bir kanal açar. Şirin onu atının üstünden izler.", "en": "In Nizami's Khusrau and Shirin, the stone carver Farhad, in love with Shirin, cuts a channel through the mountain for milk to flow. Shirin watches from her horse."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.25, "w": 0.125, "h": 0.5}, "title": {"tr": "Kanal", "en": "The channel"}, "text": {"tr": "Kayaya oyulmuş süt kanalı.", "en": "The milk channel carved into the rock."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Şirin", "en": "Shirin"}, "text": {"tr": "Atının üstündeki Şirin.", "en": "Shirin on horseback."}}, {"id": "d2", "rect": {"x": 0.125, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Ferhat", "en": "Farhad"}, "text": {"tr": "Kanalın başında duran Ferhat.", "en": "Farhad standing by the channel."}}]}, "met-451286": {"title": {"tr": "Şah Cihan'ın Rozeti", "en": "Rosette of Shah Jahan"}, "note": {"tr": "Babür albümlerinin açılış sayfalarında yer alan “şemse”, sultanın ad ve unvanlarını taşır. Merkezdeki küçük yazı altın ve lacivert bezemeyle çevrelenir.", "en": "The shamsa or sunburst opened Mughal albums and carried the emperor's names and titles. The small central inscription is framed by gold and lapis ornament."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.375, "w": 0.375, "h": 0.125}, "title": {"tr": "Merkez", "en": "The centre"}, "text": {"tr": "Şah Cihan'ın adı ve unvanlarını taşıyan orta yazı.", "en": "The central inscription with Shah Jahan's names and titles."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.25, "w": 1.0, "h": 0.5}, "title": {"tr": "Yıldız dilimleri", "en": "Rays"}, "text": {"tr": "Dilimli rozetin lacivert bezemeli uçları.", "en": "The lobed points with blue ornament."}}]}, "met-454015": {"title": {"tr": "Saz Yapraklarına Sarılmış Ejder", "en": "Dragon Wrapped around Saz Leaves"}, "note": {"tr": "“Saz üslubu” Osmanlı saray nakkaşhanesinde gelişti: kıvrık, tırtıklı yapraklar ve hayali yaratıklar. Bu çizim tek renk mürekkeple yapılmış usta bir egzersizdir.", "en": "The “saz style” flourished in the Ottoman court studio: curving, serrated leaves and fabulous creatures. This drawing is a masterful exercise in ink alone."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.25, "w": 0.375, "h": 0.375}, "title": {"tr": "Ejder", "en": "The dragon"}, "text": {"tr": "Yaprakların arasında kıvrılan ejder.", "en": "The dragon coiling among the leaves."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.0, "w": 1.0, "h": 0.25}, "title": {"tr": "Altın bordür", "en": "Gold border"}, "text": {"tr": "Sayfayı çevreleyen altın çiçek bezemesi.", "en": "The gold floral border around the page."}}]}, "met-447509": {"title": {"tr": "Üç Kemerli Halı", "en": "Carpet with Triple-Arch Design"}, "note": {"tr": "Osmanlı saray atölyelerinde ipek ve yünle dokunmuştur. Üç kemer bir yapının iç mekânını düşündürür; ortadaki kemerden bir kandil sarkar.", "en": "Woven in silk and wool in the Ottoman court workshops. The three arches suggest an interior; a lamp hangs from the middle arch."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.25, "w": 0.125, "h": 0.25}, "title": {"tr": "Kandil", "en": "The lamp"}, "text": {"tr": "Orta kemerden sarkan kandil.", "en": "The lamp hanging from the central arch."}}, {"id": "d1", "rect": {"x": 0.125, "y": 0.25, "w": 0.75, "h": 0.625}, "title": {"tr": "Kemerler", "en": "The arches"}, "text": {"tr": "İnce sütunlara oturan üç kemer.", "en": "Three arches resting on slender columns."}}]}, "met-455082": {"title": {"tr": "Bahçede Sohbet", "en": "Garden Gathering"}, "note": {"tr": "İsfahan'daki bir köşkün duvarını süsleyen çini panodur. Şapkalı bir Avrupalı ve İranlı konuklar çiçekli bir bahçede şarap ve meyve ikram edilirken görülür.", "en": "A tile panel from the wall of a pavilion in Isfahan. A European in a hat and Persian guests are served wine and fruit in a flowering garden."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.25, "w": 0.25, "h": 0.5}, "title": {"tr": "Avrupalı", "en": "The European"}, "text": {"tr": "Siyah şapkalı yabancı konuk.", "en": "The foreign guest in a black hat."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.125, "w": 0.25, "h": 0.625}, "title": {"tr": "Hizmetkârlar", "en": "Attendants"}, "text": {"tr": "Sağda ikram eden figürler.", "en": "The serving figures on the right."}}]}, "met-446567": {"title": {"tr": "Mavi Köşkün Prensesi", "en": "The Princess of the Blue Pavilion"}, "note": {"tr": "Emir Hüsrev Dehlevi'nin Heşt Behişt'inden Babür minyatürü. Rum'dan gelen genç, perilerin eşliğinde bir bahçede ağırlanır; gökte uçan bir peri ayı karşılar.", "en": "A Mughal miniature from Amir Khusrau's Hasht Bihisht. The youth from Rum is entertained by fairies in a garden; a flying peri greets the moon in the sky."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.125, "w": 0.25, "h": 0.125}, "title": {"tr": "Uçan peri", "en": "Flying peri"}, "text": {"tr": "Gökyüzünde süzülen kanatlı peri.", "en": "A winged fairy gliding in the sky."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.5, "w": 0.25, "h": 0.125}, "title": {"tr": "Genç ve prenses", "en": "Youth and princess"}, "text": {"tr": "Köşkte oturan çift.", "en": "The couple seated in the pavilion."}}]}, "met-455059": {"title": {"tr": "Kulak Misafiri", "en": "The Eavesdropper"}, "note": {"tr": "Nizami'nin Heft Peyker'inden. Bahçe sahibi Mahan, kadınların havuzda yıkandığını duvarın arkasından gözetler; Timurlu resminin zarif mimari çerçevesi içinde.", "en": "From Nizami's Haft Paikar. The garden's owner watches women bathing in the pool from behind the wall, set within the delicate architecture of Timurid painting."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.625, "w": 0.25, "h": 0.125}, "title": {"tr": "Havuz", "en": "The pool"}, "text": {"tr": "Yıkanan figürlerle dolu karanlık havuz.", "en": "The dark pool with bathing figures."}}, {"id": "d1", "rect": {"x": 0.125, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "Pencereler", "en": "Windows"}, "text": {"tr": "Köşkün renkli pencere kafesleri.", "en": "The pavilion's coloured window grilles."}}, {"id": "d2", "rect": {"x": 0.625, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Ağaçtaki figür", "en": "Figure in the tree"}, "text": {"tr": "Ağaca tırmanan gözetleyici.", "en": "The watcher climbing the tree."}}]}, "met-452135": {"title": {"tr": "Siyavuş Afrasiyab'ın Önünde Çevgen Oynuyor", "en": "Siyavush Plays Polo before Afrasiyab"}, "note": {"tr": "Çevgen (polo) İran saray kültürünün gözde oyunuydu. İranlı prens Siyavuş, Turan hükümdarı Afrasiyab'ın önünde ustalığını sergiler.", "en": "Polo was a favourite pastime of Persian court culture. The Iranian prince Siyavush shows his skill before Afrasiyab, king of Turan."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.5, "w": 0.375, "h": 0.25}, "title": {"tr": "Oyuncular", "en": "The players"}, "text": {"tr": "Sopalarını sallayan atlı oyuncular.", "en": "Riders swinging their polo sticks."}}, {"id": "d1", "rect": {"x": 0.125, "y": 0.25, "w": 0.5, "h": 0.125}, "title": {"tr": "Başlık", "en": "Heading"}, "text": {"tr": "Sayfanın üstündeki tezhipli başlık.", "en": "The illuminated heading at the top of the page."}}]}, "hokusai-wave": {"title": {"tr": "Kanagawa Açıklarında Dalganın Altında (Büyük Dalga)", "en": "The Great Wave off Kanagawa"}, "note": {"tr": "“Fuji Dağı'nın Otuz Altı Görünümü” dizisinin en ünlü baskısı. Pençe gibi kıvrılan dalga, uzaktaki küçük Fuji'yi çerçeveliyor; Hokusai burada Avrupa'dan gelen Prusya mavisini cesurca kullanır.", "en": "The best-known sheet from “Thirty-six Views of Mount Fuji”. The claw-like wave frames a tiny Fuji in the distance; Hokusai uses the newly imported Prussian blue boldly."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.5, "w": 0.25, "h": 0.25}, "title": {"tr": "Uzaktaki Fuji", "en": "Distant Fuji"}, "text": {"tr": "Dev dalganın altında Fuji, bir köpük tepesi kadar küçük görünür.", "en": "Beneath the giant wave, Fuji looks no bigger than a crest of foam."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.5, "w": 0.375, "h": 0.375}, "title": {"tr": "Kürekçiler", "en": "The rowers"}, "text": {"tr": "Uzun teknelerdeki kürekçiler başlarını eğip dalganın geçmesini bekliyor.", "en": "Rowers in the long boats bow their heads and wait for the wave to pass."}}]}, "met-56787": {"title": {"tr": "Owari'de Fujimigahara", "en": "Fujimigahara in Owari Province"}, "note": {"tr": "Bir fıçıcı dev bir fıçının içinde çalışıyor; fıçının yuvarlak gövdesi, ufuktaki Fuji için bir pencereye dönüşür. Gündelik bir iş, büyük bir manzaranın çerçevesi olur.", "en": "A cooper works inside a huge barrel whose round body becomes a window onto Fuji. An everyday task turns into the frame for a grand view."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.375, "w": 0.125, "h": 0.25}, "title": {"tr": "Fıçının içindeki Fuji", "en": "Fuji in the barrel"}, "text": {"tr": "Beyaz tepesi fıçı tahtalarının arasından görünür.", "en": "Its white peak appears between the barrel staves."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Fıçıcı", "en": "The cooper"}, "text": {"tr": "Usta, tokmağıyla fıçının içinden çemberleri sıkıştırıyor.", "en": "The craftsman tightens the hoops from inside with his mallet."}}]}, "met-36521": {"title": {"tr": "Shōno'da Ani Sağanak", "en": "Sudden Shower at Shōno"}, "note": {"tr": "Hiroshige'nin “Tōkaidō Yolunun Elli Üç Durağı” dizisinden. Eğik yağmur çizgileri ve gri tonlarla çizilmiş bambular, rüzgârın ve aceleyle koşan yolcuların hareketini neredeyse duyulur kılar.", "en": "From Hiroshige's “Fifty-three Stations of the Tōkaidō”. Slanting rain lines and grey-toned bamboo make the wind and the hurrying travellers almost audible."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.375, "w": 0.375, "h": 0.375}, "title": {"tr": "Tahtırevan taşıyıcıları", "en": "Palanquin bearers"}, "text": {"tr": "İki taşıyıcı yokuş yukarı koşarken üstü örtülü tahtırevanı sırtlanmış.", "en": "Two bearers race uphill carrying a covered palanquin."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.125, "w": 0.375, "h": 0.375}, "title": {"tr": "Bambu siluetleri", "en": "Bamboo silhouettes"}, "text": {"tr": "Arka plandaki bambular yalnızca gri tonlarla, rüzgârda eğilmiş hâlde basılmış.", "en": "The bamboo in the background is printed only in greys, bent by the wind."}}]}, "met-36492": {"title": {"tr": "Fuji'nin Eteğinde Fırtına", "en": "Storm below Mount Fuji"}, "note": {"tr": "Zirvede açık bir gökyüzü, eteklerde ise şimşekler. Hokusai aynı dağın üstünde iki ayrı havayı tek karede buluşturur.", "en": "Clear sky at the summit, lightning at the foot. Hokusai brings two kinds of weather together on a single mountain."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.625, "w": 0.375, "h": 0.375}, "title": {"tr": "Şimşekler", "en": "Lightning"}, "text": {"tr": "Kırmızı zigzaglar, karanlık eteklerde çakan şimşekleri gösterir.", "en": "Red zigzags mark lightning flashing across the dark lower slopes."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.0, "w": 0.25, "h": 0.25}, "title": {"tr": "Karlı zirve", "en": "Snowy summit"}, "text": {"tr": "Zirvedeki kar, damarlar gibi aşağı süzülür.", "en": "Snow at the peak trickles down like veins."}}]}, "met-56216": {"title": {"tr": "Noboto Koyu", "en": "Noboto Bay"}, "note": {"tr": "Sığ suya dikilmiş torii kapıları arasında, cezirde kabuklu deniz ürünü toplayan insanlar. Fuji, iki kapının arasından minicik görünür.", "en": "People gather shellfish at low tide among torii gates set in the shallows. Fuji peeks out, tiny, between two gates."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.375, "w": 0.25, "h": 0.125}, "title": {"tr": "Kapılar arasında Fuji", "en": "Fuji between the gates"}, "text": {"tr": "Dağ, büyük torii'nin direkleri arasında küçücük bir üçgendir.", "en": "The mountain is a tiny triangle between the posts of the great torii."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.625, "w": 0.5, "h": 0.375}, "title": {"tr": "Toplayıcılar", "en": "The gatherers"}, "text": {"tr": "Sepetli figürler cezirde kumu eşeleyerek midye topluyor.", "en": "Figures with baskets dig in the sand for clams at low tide."}}]}, "met-36498": {"title": {"tr": "Sagami'de Hakone Gölü", "en": "The Lake at Hakone"}, "note": {"tr": "Yeşil ve sarı tepeler, gölün mavisini sarar; Fuji bu kez sol tarafta, bulutların üzerinde sakin bir tepe olarak durur.", "en": "Green and yellow hills wrap around the blue lake; this time Fuji stands quietly on the left above the clouds."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.375, "w": 0.25, "h": 0.125}, "title": {"tr": "Fuji", "en": "Fuji"}, "text": {"tr": "Karlı tepe, kıvrımlı tepelerin arasında küçük bir beyaz üçgen.", "en": "The snowy peak is a small white triangle among the rolling hills."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.375, "w": 0.375, "h": 0.5}, "title": {"tr": "Göl", "en": "The lake"}, "text": {"tr": "Gölün mavisi, tepelerin arasından bir ırmak gibi kıvrılır.", "en": "The lake's blue winds between the hills like a river."}}]}, "met-54305": {"title": {"tr": "Horoz, Tavuk ve Civciv ile Tradeskantya", "en": "Rooster, Hen and Chicken with Spiderwort"}, "note": {"tr": "Yelpaze (uchiwa) biçiminde basılmış bir kuş ve çiçek resmi. Hokusai'nin gözlem gücü, horozun parlak tüylerinde ve mavi çiçeklerin küçük yapraklarında görülür.", "en": "A bird-and-flower picture printed for a round fan (uchiwa). Hokusai's eye for observation shows in the rooster's glossy plumage and the small blue blossoms."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.25, "w": 0.25, "h": 0.375}, "title": {"tr": "Horozun ibiği", "en": "The rooster's comb"}, "text": {"tr": "Kırmızı ibik ve sakallar, tüylerin karmaşasında hemen göze çarpar.", "en": "The red comb and wattles stand out at once amid the plumage."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.125, "w": 0.25, "h": 0.375}, "title": {"tr": "Mavi çiçekler", "en": "Blue flowers"}, "text": {"tr": "Tradeskantya'nın üç yapraklı mavi çiçekleri arka planı süsler.", "en": "The three-petalled blue spiderwort flowers decorate the background."}}]}, "met-56915": {"title": {"tr": "Kanbara'da Akşam Karı", "en": "Evening Snow at Kanbara"}, "note": {"tr": "Kanbara aslında ılık bir kasabadır ve orada kar nadirdir; Hiroshige sessiz bir karlı akşamı hayal gücüyle kurar. Sahnedeki tek ses, yolcuların karda ilerleyen adımlarıdır.", "en": "Kanbara is in fact a mild town where snow is rare; Hiroshige builds a silent snowy evening from imagination. The only sound is the travellers' steps."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Şemsiyeli yolcu", "en": "Traveller with umbrella"}, "text": {"tr": "Başını eğmiş bir yolcu karda yokuş aşağı iniyor.", "en": "A traveller, head bowed, walks down the snowy slope."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.25, "w": 0.375, "h": 0.375}, "title": {"tr": "Karlı damlar", "en": "Snowy roofs"}, "text": {"tr": "Evlerin damları kalın bir kar örtüsüyle yumuşamış.", "en": "The roofs are softened by a thick blanket of snow."}}]}, "met-55433": {"title": {"tr": "Shin-Ōhashi Köprüsü ve Atake'de Ani Sağanak", "en": "Sudden Shower over Shin-Ōhashi Bridge"}, "note": {"tr": "“Edo'nun Yüz Ünlü Manzarası” dizisinden. Van Gogh bu baskıyı o kadar beğendi ki 1887'de yağlıboyayla kopyaladı. Yağmur, ince siyah çizgilerle bir perde gibi iner.", "en": "From “One Hundred Famous Views of Edo”. Van Gogh admired it so much that he copied it in oils in 1887. The rain falls like a curtain of fine black lines."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Salcı", "en": "The raftsman"}, "text": {"tr": "Nehirde tek başına bir adam, kütük salını sırıkla itiyor.", "en": "Alone on the river, a man poles a log raft."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.5, "w": 0.375, "h": 0.25}, "title": {"tr": "Köprüdeki yolcular", "en": "People on the bridge"}, "text": {"tr": "Hasır pelerinli figürler yağmurdan kaçmak için köprüde koşuyor.", "en": "Figures in straw cloaks hurry across the bridge to escape the rain."}}]}, "met-37282": {"title": {"tr": "Komagatadō'dan Azuma Köprüsü", "en": "Azuma Bridge from Komagatadō"}, "note": {"tr": "Gece göğünde süzülen bir guguk kuşu, Sumida Nehri'nin üzerinde dalgalanan kırmızı bir bayrak. Hiroshige geniş boşluklarla sessizliği resmeder.", "en": "A cuckoo glides across the night sky; a red banner flutters above the Sumida River. Hiroshige paints silence with open space."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "Guguk kuşu", "en": "The cuckoo"}, "text": {"tr": "Kanatlarını açmış kuş, karanlık gökte beyaz bir iz bırakır.", "en": "The bird, wings spread, leaves a pale mark on the dark sky."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.5, "w": 0.25, "h": 0.25}, "title": {"tr": "Kırmızı bayrak", "en": "Red banner"}, "text": {"tr": "Uzun bir direkte dalgalanan bayrak, tek sıcak rengi taşır.", "en": "A banner on a tall pole carries the scene's only warm colour."}}]}, "met-56689": {"title": {"tr": "Asakusa'da Kinryūzan Tapınağı", "en": "Kinryūzan Temple at Asakusa"}, "note": {"tr": "Tapınak kapısındaki dev kırmızı fener, karla kaplı avluyu bir çerçeve gibi kuşatır. Ön plandaki büyük biçim ile uzaktaki küçük figürler arasındaki karşıtlık bu dizinin imzasıdır.", "en": "The giant red lantern of the temple gate frames the snowy courtyard. The contrast between the huge foreground form and the tiny distant figures is the series' signature."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.0, "w": 0.5, "h": 0.375}, "title": {"tr": "Dev fener", "en": "The giant lantern"}, "text": {"tr": "Kapının fenerinin üzerinde tapınağın adı yazılıdır.", "en": "The temple's name is written on the gate lantern."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.5, "w": 0.25, "h": 0.25}, "title": {"tr": "Pagoda", "en": "Pagoda"}, "text": {"tr": "Karın ardında beş katlı pagodanın kırmızı katları görünür.", "en": "The red storeys of the five-storey pagoda show through the snow."}}]}, "met-36543": {"title": {"tr": "Uchikawa'da Suijin Tapınağı Korusu ve Sekiya Köyü", "en": "Suijin Temple Grove and Sekiya Village"}, "note": {"tr": "Manzaraya yuvarlak bir pencereden bakıyoruz; önde çiçek açmış bir erik dalı, uzakta nehir ve sazlıklar. Hiroshige izleyiciyi bir çay evinin içine oturtur.", "en": "We look at the view through a round window: a flowering plum branch in front, the river and reeds beyond. Hiroshige seats the viewer inside a teahouse."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.375, "w": 0.375, "h": 0.625}, "title": {"tr": "Erik dalı", "en": "Plum branch"}, "text": {"tr": "Pencerenin önünde, beyaz çiçekli ince bir erik dalı yükselir.", "en": "A slender plum branch with white blossoms rises before the window."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.25, "w": 0.25, "h": 0.25}, "title": {"tr": "Kuş sürüsü", "en": "Flock of birds"}, "text": {"tr": "Göğe doğru uçan küçük bir kuş sürüsü.", "en": "A small flock of birds flying across the sky."}}]}, "braun-alexandria": {"title": {"tr": "İskenderiye Haritası", "en": "Map of Alexandria"}, "note": {"tr": "Braun ve Hogenberg'in “Civitates Orbis Terrarum” atlası, dünyanın şehirlerini sistemli biçimde toplayan ilk büyük atlastır. İskenderiye surları ve limanı elle renklendirilmiş.", "en": "Braun and Hogenberg's “Civitates Orbis Terrarum” was the first great atlas to collect the cities of the world systematically. Alexandria's walls and harbour are hand-coloured."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.625, "w": 0.375, "h": 0.25}, "title": {"tr": "Limandaki gemiler", "en": "Ships in the harbour"}, "text": {"tr": "Yelkenli gemiler limana yaklaşıyor.", "en": "Sailing ships approach the harbour."}}, {"id": "d1", "rect": {"x": 0.125, "y": 0.875, "w": 0.625, "h": 0.125}, "title": {"tr": "Akdeniz", "en": "The Mediterranean"}, "text": {"tr": "Haritanın altında Latince “Mediterraneum Mare” yazısı.", "en": "The Latin “Mediterraneum Mare” along the bottom."}}]}, "tempesta-rome": {"title": {"tr": "Roma Şehir Planı, 12. pafta", "en": "Plan of the City of Rome, Part 12"}, "note": {"tr": "Antonio Tempesta'nın kuşbakışı Roma planı on iki paftadan oluşur. Bu pafta, imzalı büyük kartuşu ve Roma'yı temsil eden figürü taşır.", "en": "Antonio Tempesta's bird's-eye plan of Rome is made of twelve sheets. This one carries the large signed cartouche and the figure personifying Rome."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.625, "w": 0.375, "h": 0.25}, "title": {"tr": "Kartuş", "en": "Cartouche"}, "text": {"tr": "Tempesta'nın adı ve tarihi taşıyan yazı alanı.", "en": "The panel bearing Tempesta's name and date."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.875, "w": 0.875, "h": 0.125}, "title": {"tr": "Semt amblemleri", "en": "District emblems"}, "text": {"tr": "Roma'nın on dört semtinin (rione) simgeleri.", "en": "The emblems of Rome's fourteen districts (rioni)."}}]}, "met-366878": {"title": {"tr": "Anvers Görünümü", "en": "View of Antwerp"}, "note": {"tr": "Joris Hoefnagel, Braun ve Hogenberg'in atlası için şehirler çizdi. Anvers'in yıldız biçimli kalesi ve ön plandaki yerel kıyafetli figürler bu sayfanın tadıdır.", "en": "Joris Hoefnagel drew cities for Braun and Hogenberg's atlas. Antwerp's star-shaped citadel and the figures in local dress in the foreground give the sheet its charm."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Yıldız kale", "en": "Star fort"}, "text": {"tr": "Şehrin güneyindeki beş köşeli kale.", "en": "The five-pointed citadel south of the city."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.75, "w": 0.25, "h": 0.125}, "title": {"tr": "Kıyafetli figürler", "en": "Figures in costume"}, "text": {"tr": "Dönemin Anvers kıyafetlerini gösteren kişiler.", "en": "People shown in the dress of the period."}}]}, "met-358366": {"title": {"tr": "Gökyüzü Haritası: Kuzey Yarıküre", "en": "The Celestial Map – Northern Hemisphere"}, "note": {"tr": "Dürer'in 1515 tarihli ağaç baskısı, basılmış ilk yıldız haritalarındandır. Takımyıldızlar figürlerle çizilmiş; köşelerde dört ünlü gökbilimci yer alır.", "en": "Dürer's woodcut of 1515 is among the first printed star charts. Constellations are drawn as figures, with four famous astronomers in the corners."}, "details": [{"id": "d0", "rect": {"x": 0.75, "y": 0.0, "w": 0.25, "h": 0.25}, "title": {"tr": "Batlamyus", "en": "Ptolemy"}, "text": {"tr": "Sağ üst köşede “Ptolemaeus Aegyptius”.", "en": "“Ptolemaeus Aegyptius” in the top right corner."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.75, "w": 0.25, "h": 0.25}, "title": {"tr": "Sufi", "en": "Al-Sufi"}, "text": {"tr": "Sağ altta İranlı gökbilimci Abdurrahman es-Sufi (Azophi).", "en": "The Persian astronomer al-Sufi (Azophi) at lower right."}}]}, "met-587682": {"title": {"tr": "Günümüz Mısırı Haritası", "en": "Aegyptus Hodierna, Map of Egypt"}, "note": {"tr": "Nürnbergli haritacı Homann'ın elle renklendirilmiş Mısır haritası. Nil vadisi kuzeyden güneye uzanır; sol alttaki süslemede piramitler ve antik kalıntılar görülür.", "en": "Hand-coloured map of Egypt by the Nuremberg cartographer Homann. The Nile valley runs north to south; the lower-left vignette shows pyramids and ancient ruins."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.0, "w": 0.375, "h": 0.25}, "title": {"tr": "Nil Deltası", "en": "The Nile Delta"}, "text": {"tr": "Pembeyle boyanmış delta bölgesi.", "en": "The delta region tinted in pink."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.5, "w": 0.375, "h": 0.375}, "title": {"tr": "Piramitler", "en": "Pyramids"}, "text": {"tr": "Sol alttaki resimli süslemede piramitler.", "en": "Pyramids in the pictorial vignette at lower left."}}]}, "met-403169": {"title": {"tr": "Yunanistan Haritası", "en": "Map of Greece"}, "note": {"tr": "Roma'da basılan “Speculum Romanae Magnificentiae” koleksiyonundan bir gravür. Ege adaları, denizdeki gemiler ve sol alttaki kartuşla dönemin coğrafya merakını yansıtır.", "en": "An engraving from the “Speculum Romanae Magnificentiae”, published in Rome. Aegean islands, ships at sea and the cartouche at lower left reflect the period's curiosity about geography."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.625, "w": 0.25, "h": 0.375}, "title": {"tr": "Kartuş", "en": "Cartouche"}, "text": {"tr": "Sol alttaki süslü yazı çerçevesi.", "en": "The ornate text frame at lower left."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.75, "w": 0.25, "h": 0.25}, "title": {"tr": "Gemiler", "en": "Ships"}, "text": {"tr": "Denizde küçük yelkenliler.", "en": "Small sailing ships at sea."}}]}, "met-381436": {"title": {"tr": "Roma Şehir Planı", "en": "Plan of the City of Rome"}, "note": {"tr": "Tempesta'nın planının tamamı: on iki pafta birleşince Roma kuşbakışı tek bir panoramaya dönüşür. Tiber Nehri şehri bir yay gibi ikiye böler.", "en": "Tempesta's complete plan: joined together, the twelve sheets become a single bird's-eye panorama of Rome. The Tiber divides the city like a bow."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.0, "w": 0.125, "h": 0.25}, "title": {"tr": "Arma", "en": "Coat of arms"}, "text": {"tr": "Sol üstte papalık arması.", "en": "Papal coat of arms at top left."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.25, "w": 0.375, "h": 0.375}, "title": {"tr": "Tiber", "en": "The Tiber"}, "text": {"tr": "Şehrin içinden kıvrılan nehir.", "en": "The river winding through the city."}}]}, "met-386248": {"title": {"tr": "New York Şehri Planı (James Lyne, 1728)", "en": "A Plan of the City of New York, 1728"}, "note": {"tr": "Manhattan'ın güney ucunun en erken basılı planlarından birinin 19. yüzyıl tıpkıbasımı. Sokaklar, “Common” alanı ve limandaki gemiler şehrin küçük bir liman kasabası olduğu günleri gösterir.", "en": "A 19th-century facsimile of one of the earliest printed plans of lower Manhattan. Streets, the Common and the ships in the harbour recall when the city was a small port town."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "Kartuş", "en": "Cartouche"}, "text": {"tr": "Figürlerle çevrili açıklama alanı.", "en": "The text panel framed by figures."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.25, "w": 0.25, "h": 0.25}, "title": {"tr": "“Common”", "en": "The Common"}, "text": {"tr": "Bugünkü City Hall Park'ın yeri.", "en": "The site of today's City Hall Park."}}]}, "met-380748": {"title": {"tr": "New York Şehri: Longworth'ün Açıklamalı Haritası", "en": "Longworth's Explanatory Map of New York"}, "note": {"tr": "1817 tarihli bu harita, Manhattan'ı kaplamaya başlayan ünlü ızgara sokak planını gösterir. Üstte şehrin önemli binalarının cepheleri sıralanır.", "en": "This 1817 map shows the famous street grid beginning to cover Manhattan. The façades of the city's important buildings run along the top."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.0, "w": 0.625, "h": 0.125}, "title": {"tr": "Bina cepheleri", "en": "Building façades"}, "text": {"tr": "Üst şeritte şehrin binaları.", "en": "The city's buildings along the top band."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.25, "w": 0.375, "h": 0.5}, "title": {"tr": "Izgara", "en": "The grid"}, "text": {"tr": "Düzenli sokak ızgarası adanın kuzeyine yayılıyor.", "en": "The regular street grid spreading north up the island."}}]}, "met-857002": {"title": {"tr": "Inn Vadisi", "en": "The Inn Valley"}, "note": {"tr": "Braun ve Hogenberg atlasının beşinci cildinden Alp manzaraları. Dik kayalıklar, vadideki köyler ve yollar elle renklendirilmiş.", "en": "Alpine views from the fifth volume of Braun and Hogenberg's atlas. Steep cliffs, villages and roads in the valley are coloured by hand."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Anıt", "en": "Monument"}, "text": {"tr": "Alt sağdaki resimde kayalık üstünde bir anıt.", "en": "A monument on a rock in the lower right scene."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.75, "w": 0.25, "h": 0.125}, "title": {"tr": "Atlılar", "en": "Riders"}, "text": {"tr": "Yolda ilerleyen küçük atlı figürler.", "en": "Small mounted figures on the road."}}]}, "met-358826": {"title": {"tr": "Antik Roma Planı", "en": "Plan of Ancient Rome"}, "note": {"tr": "On altı ayrı paftanın birleştirilmesiyle oluşan bu plan, antik Roma'nın yapılarını haritaya yerleştirir. Köşelerde Pantheon ve bir zafer takı görünümleri yer alır.", "en": "Made from sixteen joined sheets, this plan places the buildings of ancient Rome on the map. The corners show views of the Pantheon and a triumphal arch."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.75, "w": 0.25, "h": 0.25}, "title": {"tr": "Pantheon", "en": "Pantheon"}, "text": {"tr": "Sol altta Pantheon'un görünümü.", "en": "A view of the Pantheon at lower left."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.0, "w": 0.125, "h": 0.25}, "title": {"tr": "Rüzgâr gülü", "en": "Compass rose"}, "text": {"tr": "Sağ üstte yön gösteren rüzgâr gülü.", "en": "The compass rose at top right."}}]}, "met-711314": {"title": {"tr": "Jain Kozmolojisi: İki Buçuk Kıta (Adhai-dvipa)", "en": "Jain Cosmological Map of Adhaidvipa"}, "note": {"tr": "Jain inancında insanların yaşayabildiği dünya, iç içe geçmiş kıtalar ve okyanuslardan oluşur. Bu baskı, merkezdeki Jambudvipa'yı ve onu saran halkaları şematik bir harita olarak gösterir.", "en": "In Jain cosmology the world humans can inhabit is made of concentric continents and oceans. This print shows central Jambudvipa and the rings around it as a schematic map."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.375, "w": 0.5, "h": 0.25}, "title": {"tr": "Jambudvipa", "en": "Jambudvipa"}, "text": {"tr": "Merkezdeki dikdörtgen kıta.", "en": "The central continent."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.125, "w": 0.125, "h": 0.25}, "title": {"tr": "Köşe figürleri", "en": "Corner figures"}, "text": {"tr": "Köşelerde süsleyici figürler.", "en": "Decorative figures in the corners."}}]}, "bruegel-harvesters": {"title": {"tr": "Hasatçılar", "en": "The Harvesters"}, "note": {"tr": "Bruegel'in yılın aylarını anlatan altı tablosundan biri; Ağustos ya da Eylül'ü temsil eder. Öğle sıcağında dinlenen köylüler, Batı resminde ilk “gerçek” manzaralardan birinin içindedir.", "en": "One of Bruegel's six paintings of the seasons, representing August or September. Peasants resting in the midday heat sit inside one of the first “true” landscapes of Western painting."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.625, "w": 0.375, "h": 0.25}, "title": {"tr": "Öğle yemeği", "en": "Midday meal"}, "text": {"tr": "Armut ağacının altında yemek yiyen hasatçılar.", "en": "Harvesters eating beneath the pear tree."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.625, "w": 0.125, "h": 0.25}, "title": {"tr": "Uyuyan adam", "en": "The sleeper"}, "text": {"tr": "Ağaca yaslanmış uyuyan köylü.", "en": "A peasant asleep against the tree."}}, {"id": "d2", "rect": {"x": 0.0, "y": 0.25, "w": 0.5, "h": 0.25}, "title": {"tr": "Uzak manzara", "en": "Distant view"}, "text": {"tr": "Köyler, kilise ve ufukta deniz.", "en": "Villages, a church and the sea on the horizon."}}]}, "met-436575": {"title": {"tr": "Toledo Manzarası", "en": "View of Toledo"}, "note": {"tr": "El Greco'nun günümüze ulaşan iki manzarasından biri. Fırtınalı gökyüzü altında şehir gerçek konumundan farklı düzenlenmiş; katedral çan kulesi bilerek yer değiştirmiştir.", "en": "One of El Greco's two surviving landscapes. Beneath the stormy sky the city is rearranged; the cathedral tower has been deliberately moved."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.25, "w": 0.125, "h": 0.25}, "title": {"tr": "Katedral", "en": "The cathedral"}, "text": {"tr": "Toledo Katedrali'nin çan kulesi.", "en": "The bell tower of Toledo Cathedral."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.25, "w": 0.25, "h": 0.25}, "title": {"tr": "Alcázar", "en": "The Alcázar"}, "text": {"tr": "Tepedeki kare saray.", "en": "The square palace on the hilltop."}}, {"id": "d2", "rect": {"x": 0.0, "y": 0.0, "w": 1.0, "h": 0.25}, "title": {"tr": "Fırtınalı gök", "en": "Stormy sky"}, "text": {"tr": "Yeşil-gri bulutlar.", "en": "Green-grey clouds."}}]}, "met-459016": {"title": {"tr": "Müjde", "en": "The Annunciation"}, "note": {"tr": "Botticelli'nin küçük boyutlu bir sunak parçası. Melek Cebrail, Meryem'e İsa'yı doğuracağını müjdeler; perspektifle derinleşen sütunlar ikisini ayırır.", "en": "A small panel by Botticelli. The angel Gabriel announces to Mary that she will bear Christ; columns receding in perspective separate the two."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.375, "w": 0.25, "h": 0.375}, "title": {"tr": "Melek", "en": "The angel"}, "text": {"tr": "Elinde zambakla diz çöken Cebrail.", "en": "Gabriel kneeling with a lily."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.375, "w": 0.25, "h": 0.375}, "title": {"tr": "Meryem", "en": "Mary"}, "text": {"tr": "Başını eğmiş Meryem.", "en": "Mary with her head bowed."}}, {"id": "d2", "rect": {"x": 0.25, "y": 0.25, "w": 0.125, "h": 0.125}, "title": {"tr": "Pencere", "en": "Window"}, "text": {"tr": "Odanın arkasındaki kemerli pencereler.", "en": "The arched windows at the back of the room."}}]}, "met-437326": {"title": {"tr": "Doğan Güneşi Arayan Kör Orion", "en": "Blind Orion Searching for the Rising Sun"}, "note": {"tr": "Kör edilen dev avcı Orion, omzundaki Kedalion'un yol göstermesiyle iyileştirici güneşe doğru yürür. Bulutların üstünde tanrıça Diana izler.", "en": "The blinded giant hunter Orion strides toward the healing sun, guided by Cedalion on his shoulders. The goddess Diana watches from the clouds."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.25, "w": 0.25, "h": 0.625}, "title": {"tr": "Orion", "en": "Orion"}, "text": {"tr": "Dev adımlarla yürüyen kör avcı.", "en": "The blind hunter striding forward."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.125, "w": 0.125, "h": 0.25}, "title": {"tr": "Kedalion", "en": "Cedalion"}, "text": {"tr": "Orion'un omzunda yol gösteren figür.", "en": "The guide on Orion's shoulders."}}, {"id": "d2", "rect": {"x": 0.5, "y": 0.125, "w": 0.25, "h": 0.125}, "title": {"tr": "Diana", "en": "Diana"}, "text": {"tr": "Bulutlarda yaslanan tanrıça.", "en": "The goddess leaning on a cloud."}}]}, "met-436570": {"title": {"tr": "Çobanların Tapınması", "en": "The Adoration of the Shepherds"}, "note": {"tr": "El Greco'nun son eserlerinden; kendi mezar şapeli için yaptığı düşünülür. Işık bebek İsa'dan yayılır ve uzayan figürler karanlıktan çıkar.", "en": "One of El Greco's last works, thought to have been made for his own burial chapel. Light radiates from the Christ Child and elongated figures emerge from darkness."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Bebek İsa", "en": "The Christ Child"}, "text": {"tr": "Işığın kaynağı olan bebek.", "en": "The infant who is the source of light."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.0, "w": 0.375, "h": 0.25}, "title": {"tr": "Melekler", "en": "Angels"}, "text": {"tr": "Yukarıda dönen melekler.", "en": "Angels swirling above."}}, {"id": "d2", "rect": {"x": 0.125, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Kuzu", "en": "The lamb"}, "text": {"tr": "Altta bağlı kuzu.", "en": "The bound lamb below."}}]}, "met-437824": {"title": {"tr": "Meryem ve Çocuk", "en": "Madonna and Child"}, "note": {"tr": "Genç Titian'ın Giorgione etkisindeki erken eserlerinden. Meryem'in mavi pelerini ve kırmızı elbisesi Venedik renkçiliğinin habercisidir.", "en": "An early work by the young Titian, under Giorgione's influence. Mary's blue mantle and red dress herald the Venetian love of colour."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.5, "w": 0.375, "h": 0.25}, "title": {"tr": "Çocuk İsa", "en": "The Child"}, "text": {"tr": "Meryem'in kucağında uyuklayan bebek.", "en": "The infant dozing in Mary's lap."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.0, "w": 0.25, "h": 0.375}, "title": {"tr": "Manzara", "en": "Landscape"}, "text": {"tr": "Arkadaki mavi gök ve ağaç.", "en": "The blue sky and tree behind."}}]}, "met-437536": {"title": {"tr": "Kurt ve Tilki Avı", "en": "Wolf and Fox Hunt"}, "note": {"tr": "Rubens'in hareket dolu av sahnelerinden. Atlılar, mızraklar, köpekler ve kurtlar dev bir kompozisyonda birbirine dolanır.", "en": "One of Rubens's action-packed hunting scenes. Riders, spears, dogs and wolves tangle in one great composition."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.375, "w": 0.25, "h": 0.375}, "title": {"tr": "Kurt", "en": "The wolf"}, "text": {"tr": "Köpeklerle boğuşan kurt.", "en": "The wolf fighting the dogs."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.0, "w": 0.375, "h": 0.25}, "title": {"tr": "Atlı avcılar", "en": "Mounted hunters"}, "text": {"tr": "Sağ üstte yeşil giysili avcı ve şahin taşıyan kadın.", "en": "The hunter in green and the woman with a falcon, upper right."}}, {"id": "d2", "rect": {"x": 0.625, "y": 0.75, "w": 0.25, "h": 0.125}, "title": {"tr": "Tilki", "en": "The fox"}, "text": {"tr": "Altta yakalanmış tilki.", "en": "The captured fox below."}}]}, "met-459001": {"title": {"tr": "Çocuğa Tapan Meryem", "en": "Madonna Adoring the Child"}, "note": {"tr": "Botticelli'nin küçük bir adanmışlık paneli. Meryem diz çöker; arkadaki şehir ve yıkıntılar, eski dünyanın sona erişini simgeler.", "en": "A small devotional panel by Botticelli. Mary kneels; the town and ruins behind symbolise the passing of the old world."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.625, "w": 0.375, "h": 0.25}, "title": {"tr": "Bebek", "en": "The Child"}, "text": {"tr": "Yerdeki pelerine uzanmış bebek.", "en": "The infant lying on the mantle."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.25, "w": 0.375, "h": 0.25}, "title": {"tr": "Şehir", "en": "The town"}, "text": {"tr": "Arkadaki kuleli şehir.", "en": "The towered town behind."}}]}, "met-435905": {"title": {"tr": "Sığ Geçit", "en": "The Ford"}, "note": {"tr": "Claude Lorrain ideal manzaranın ustasıdır: ağaçlar sahneyi çerçeveler, ışık suyun üstünden ufka doğru açılır. Ön planda sürü ve çobanlar geçidi kullanır.", "en": "Claude Lorrain was the master of the ideal landscape: trees frame the scene and light opens across the water to the horizon. Herdsmen and their flock use the ford in the foreground."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.75, "w": 0.375, "h": 0.125}, "title": {"tr": "Çobanlar", "en": "Herdsmen"}, "text": {"tr": "Ön plandaki figürler.", "en": "The figures in the foreground."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.5, "w": 0.25, "h": 0.25}, "title": {"tr": "Köprü", "en": "The bridge"}, "text": {"tr": "Uzakta nehrin üstünde köprü.", "en": "A bridge across the river in the distance."}}]}, "met-437812": {"title": {"tr": "Kırda Dans", "en": "A Dance in the Country"}, "note": {"tr": "Tiepolo'nun oğlu Domenico, Venedik'in eğlence hayatını hafif bir ironiyle resmeder. Maskeli figürler ve köylüler bahçe duvarının önünde dans eder.", "en": "Tiepolo's son Domenico paints Venetian pleasures with gentle irony. Masked figures and country folk dance before a garden wall."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.5, "w": 0.25, "h": 0.25}, "title": {"tr": "Dans eden çift", "en": "Dancing couple"}, "text": {"tr": "Kırmızılı adam ve partneri.", "en": "The man in red and his partner."}}, {"id": "d1", "rect": {"x": 0.625, "y": 0.0, "w": 0.125, "h": 0.5}, "title": {"tr": "Merdiven", "en": "The ladder"}, "text": {"tr": "Ağaca dayalı merdivende izleyiciler.", "en": "Onlookers on a ladder against the tree."}}, {"id": "d2", "rect": {"x": 0.125, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Köpek", "en": "The dog"}, "text": {"tr": "Benekli av köpeği.", "en": "A spotted hound."}}]}, "met-438026": {"title": {"tr": "Aurora'nın Arabası", "en": "The Chariot of Aurora"}, "note": {"tr": "Bir tavan freskinin hazırlık eskizi. Şafak tanrıçası Aurora gökte yükselir, beyaz atlar ışığı taşır; aşağıdan bakış etkisi bilinçlidir.", "en": "A sketch for a ceiling fresco. Aurora, goddess of dawn, rises in the sky while white horses carry the light; the view from below is deliberate."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "Aurora", "en": "Aurora"}, "text": {"tr": "Işık halesiyle yükselen tanrıça.", "en": "The goddess rising with a halo of light."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.375, "w": 0.375, "h": 0.25}, "title": {"tr": "Beyaz atlar", "en": "White horses"}, "text": {"tr": "Arabayı çeken atlar.", "en": "The horses pulling the chariot."}}, {"id": "d2", "rect": {"x": 0.625, "y": 0.25, "w": 0.375, "h": 0.25}, "title": {"tr": "Kartal", "en": "The eagle"}, "text": {"tr": "Sağda kanatlarını açmış kuş.", "en": "The bird with outspread wings at right."}}]}, "met-437373": {"title": {"tr": "Giuliano de' Medici, Nemours Dükü", "en": "Giuliano de' Medici, Duke of Nemours"}, "note": {"tr": "Raphael'e atfedilen bu portre, Papa X. Leo'nun kardeşini gösterir. Sağdaki pencereden Castel Sant'Angelo görünür.", "en": "Attributed to Raphael, this portrait shows the brother of Pope Leo X. Castel Sant'Angelo is visible through the window at right."}, "details": [{"id": "d0", "rect": {"x": 0.75, "y": 0.25, "w": 0.25, "h": 0.25}, "title": {"tr": "Castel Sant'Angelo", "en": "Castel Sant'Angelo"}, "text": {"tr": "Pencereden görünen Roma kalesi.", "en": "The Roman fortress seen through the window."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.75, "w": 0.375, "h": 0.25}, "title": {"tr": "Eller ve mektup", "en": "Hands and letter"}, "text": {"tr": "Elinde katlanmış kâğıt.", "en": "A folded paper in his hand."}}, {"id": "d2", "rect": {"x": 0.125, "y": 0.0, "w": 0.5, "h": 0.25}, "title": {"tr": "Şapka", "en": "The cap"}, "text": {"tr": "Altın fileli siyah bere.", "en": "The black beret with gold net."}}]}, "fantin-still-life": {"title": {"tr": "Çiçekler ve Meyvelerle Natürmort", "en": "Still Life with Flowers and Fruit"}, "note": {"tr": "Fantin-Latour, Manet ve Whistler'ın yakın dostuydu ama en çok sessiz natürmortlarıyla tanındı. Gri fon, meyvelerin sarısını ve çiçeklerin morunu öne çıkarır.", "en": "Fantin-Latour was a close friend of Manet and Whistler but became best known for his quiet still lifes. The grey ground makes the yellow fruit and violet flowers stand out."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.625, "w": 0.25, "h": 0.125}, "title": {"tr": "Kesilmiş armut", "en": "Cut pear"}, "text": {"tr": "Masanın kenarında yarıya kesilmiş bir armut.", "en": "A pear cut in half on the edge of the table."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.625, "w": 0.375, "h": 0.25}, "title": {"tr": "Bıçak", "en": "The knife"}, "text": {"tr": "Masadan taşan bıçak, derinliği ve gerçekliği artırır.", "en": "A knife projecting over the table edge adds depth and realism."}}]}, "deheem-banquet": {"title": {"tr": "Natürmort: Ziyafet Sahnesi", "en": "Still Life: A Banqueting Scene"}, "note": {"tr": "De Heem, Hollanda'nın gösterişli “pronk” natürmortlarının ustasıdır. Istakoz, gümüş kaplar, meyve ve köşedeki saat; bolluğun yanında zamanın geçiciliğini de hatırlatır.", "en": "De Heem was a master of the lavish Dutch “pronk” still life. Lobster, silver, fruit and the clock in the corner speak of abundance and of time passing."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.5, "w": 0.25, "h": 0.125}, "title": {"tr": "Istakoz", "en": "The lobster"}, "text": {"tr": "Kırmızı ıstakoz, karanlık zeminde en parlak renk.", "en": "The red lobster is the brightest colour against the dark ground."}}, {"id": "d1", "rect": {"x": 0.875, "y": 0.0, "w": 0.125, "h": 0.25}, "title": {"tr": "Saat", "en": "The clock"}, "text": {"tr": "Sağ üst köşede yarı karanlıkta bir saat kadranı.", "en": "A clock face half in shadow in the top right corner."}}]}, "met-922227": {"title": {"tr": "Roemer Kadehinde Çiçek Buketi", "en": "Bouquet of Flowers in a Roemer"}, "note": {"tr": "Bosschaert'in buketi gerçek değil: bu çiçekler aynı mevsimde açmaz. Ressam her birini ayrı ayrı çizip ideal bir buket kurmuştur; arkada sakin bir manzara uzanır.", "en": "Bosschaert's bouquet is not real: these flowers never bloom in the same season. He studied each separately and composed an ideal bouquet before a calm landscape."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Roemer kadehi", "en": "The roemer"}, "text": {"tr": "Çiçekler, Hollanda'ya özgü kabartmalı bir şarap kadehinde duruyor.", "en": "The flowers stand in a typically Dutch knobbed wine glass."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.75, "w": 0.25, "h": 0.25}, "title": {"tr": "Kelebek", "en": "Butterfly"}, "text": {"tr": "Rafın kenarında küçük bir kelebek.", "en": "A small butterfly on the ledge."}}]}, "met-436305": {"title": {"tr": "Natürmort", "en": "Still Life"}, "note": {"tr": "Georg Flegel, Almanya'daki ilk natürmort ustalarındandır. Ekmeği gagalayan küçük kuş, durağan sahneye hayat katar.", "en": "Georg Flegel was one of the first still-life specialists in Germany. The little bird pecking at the bread brings the quiet scene to life."}, "details": [{"id": "d0", "rect": {"x": 0.5, "y": 0.25, "w": 0.125, "h": 0.25}, "title": {"tr": "Kuş", "en": "The bird"}, "text": {"tr": "Bir mavi baştankara ekmeğin üstünde.", "en": "A blue tit perches on the bread."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Limon", "en": "Lemon"}, "text": {"tr": "Yarıya kesilmiş limonun içi ışıkta parlıyor.", "en": "The inside of a halved lemon glows in the light."}}]}, "met-436294": {"title": {"tr": "Hercai Menekşeli Natürmort", "en": "Still Life with Pansies"}, "note": {"tr": "Fantin-Latour'un çiçekleri İngiltere'de çok sevildi ve satıldı. Saksılardaki hercai menekşeler, koyu fonda kadife gibi görünür.", "en": "Fantin-Latour's flowers were much loved and sold in England. The pansies in their pots look like velvet against the dark ground."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.375, "w": 0.375, "h": 0.25}, "title": {"tr": "Hercai menekşeler", "en": "Pansies"}, "text": {"tr": "Sarı ve mor çiçeklerin yüzleri izleyiciye dönük.", "en": "The yellow and violet faces of the flowers turn toward us."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Elmalar", "en": "Apples"}, "text": {"tr": "Sağda dalıyla birlikte duran elmalar.", "en": "Apples with their leaves on the right."}}]}, "met-437429": {"title": {"tr": "Şeftalili Natürmort", "en": "Still Life with Peaches"}, "note": {"tr": "Renoir şeftalileri mavi beyaz bir kâsede, desenli bir fonun önünde boyar. Renkler sıcak, fırça yumuşak ve hızlıdır.", "en": "Renoir paints peaches in a blue-and-white bowl before a patterned backdrop. The colours are warm, the brush soft and quick."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.5, "w": 0.625, "h": 0.25}, "title": {"tr": "Kâse", "en": "The bowl"}, "text": {"tr": "Mavi desenli porselen kâse, şeftalilerin sıcaklığını dengeler.", "en": "The blue-patterned porcelain bowl balances the warmth of the peaches."}}, {"id": "d1", "rect": {"x": 0.0, "y": 0.625, "w": 0.375, "h": 0.25}, "title": {"tr": "Armutlar", "en": "Pears"}, "text": {"tr": "Masa örtüsünün üzerinde dağınık armutlar.", "en": "Pears scattered across the tablecloth."}}]}, "met-435663": {"title": {"tr": "Istakozlu ve Meyveli Natürmort", "en": "Still Life with Lobster and Fruit"}, "note": {"tr": "Van Beyeren gümüşün, camın ve kabuğun ışığını karanlık bir fonda yakalar. Sarkan limon kabuğu, Hollanda natürmortlarının sevilen bir ustalık gösterisidir.", "en": "Van Beyeren catches the light on silver, glass and shell against a dark ground. The hanging lemon peel is a favourite virtuoso touch of Dutch still life."}, "details": [{"id": "d0", "rect": {"x": 0.0, "y": 0.625, "w": 0.25, "h": 0.125}, "title": {"tr": "Istakoz", "en": "The lobster"}, "text": {"tr": "Masanın kenarında kırmızı bir ıstakoz.", "en": "A red lobster on the edge of the table."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.625, "w": 0.125, "h": 0.25}, "title": {"tr": "Limon kabuğu", "en": "Lemon peel"}, "text": {"tr": "Spiral hâlinde sarkan limon kabuğu.", "en": "A lemon peel hanging in a spiral."}}]}, "met-437999": {"title": {"tr": "Çaydanlık ve Meyveli Natürmort", "en": "Still Life with Teapot and Fruit"}, "note": {"tr": "Gauguin bu natürmortu Tahiti'de, 1896'da yaptı. Avrupa natürmort geleneğini parlak tropik renklerle ve düz yüzeylerle yeniden yorumlar.", "en": "Gauguin painted this still life in Tahiti in 1896, reinterpreting the European tradition with bright tropical colours and flat planes."}, "details": [{"id": "d0", "rect": {"x": 0.125, "y": 0.125, "w": 0.25, "h": 0.125}, "title": {"tr": "Sarı çiçek", "en": "Yellow flower"}, "text": {"tr": "Duvar kâğıdındaki iri sarı çiçek motifi.", "en": "A large yellow flower motif on the wallpaper."}}, {"id": "d1", "rect": {"x": 0.75, "y": 0.25, "w": 0.25, "h": 0.375}, "title": {"tr": "Mangolar", "en": "Mangoes"}, "text": {"tr": "Sağdaki olgun mangolar.", "en": "Ripe mangoes on the right."}}]}, "met-436805": {"title": {"tr": "Meyve, Cam Kaplar ve Wanli Kâsesiyle Natürmort", "en": "Still Life with Fruit, Glassware, and a Wanli Bowl"}, "note": {"tr": "Kalf'in lüks natürmortlarında Çin porseleni, Venedik camı ve soyulmuş limon karanlıktan parlar. Wanli kâsesi, Hollanda'nın Asya ticaretini anlatır.", "en": "In Kalf's luxurious still lifes, Chinese porcelain, Venetian glass and a peeled lemon glow out of the dark. The Wanli bowl speaks of Dutch trade with Asia."}, "details": [{"id": "d0", "rect": {"x": 0.25, "y": 0.625, "w": 0.25, "h": 0.25}, "title": {"tr": "Soyulmuş limon", "en": "Peeled lemon"}, "text": {"tr": "Limon kabuğu tabaktan aşağı sarkar.", "en": "The lemon peel spills down from the dish."}}, {"id": "d1", "rect": {"x": 0.375, "y": 0.25, "w": 0.125, "h": 0.375}, "title": {"tr": "İnce kadeh", "en": "Tall glass"}, "text": {"tr": "Karanlıkta zar zor seçilen uzun bir cam kadeh.", "en": "A tall glass barely visible in the darkness."}}]}, "met-436634": {"title": {"tr": "Bir Vazo Çiçek", "en": "A Vase of Flowers"}, "note": {"tr": "Margareta Haverman, Jan van Huysum'un öğrencisiydi ve 1722'de Paris Kraliyet Akademisi'ne kabul edilen ilk kadınlardan biri oldu. Buket, karanlık bir nişte ışıkla açılır.", "en": "Margareta Haverman studied with Jan van Huysum and in 1722 became one of the first women admitted to the Royal Academy in Paris. The bouquet blooms with light in a dark niche."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.125, "w": 0.25, "h": 0.125}, "title": {"tr": "Lale", "en": "Tulip"}, "text": {"tr": "Buketin tepesinde çizgili bir lale.", "en": "A striped tulip at the top of the bouquet."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.75, "w": 0.25, "h": 0.125}, "title": {"tr": "Üzümler", "en": "Grapes"}, "text": {"tr": "Alttaki yeşil üzüm salkımı.", "en": "The bunch of green grapes below."}}]}, "met-435882": {"title": {"tr": "Elmalar ve Çuha Çiçeği Saksısıyla Natürmort", "en": "Still Life with Apples and a Pot of Primroses"}, "note": {"tr": "Bu tablo bir zamanlar Claude Monet'nin koleksiyonundaydı. Cézanne elmaları ve kıvrımlı örtüyü sağlam, neredeyse heykelsi biçimler olarak kurar.", "en": "This painting once belonged to Claude Monet. Cézanne builds the apples and folded cloth as solid, almost sculptural forms."}, "details": [{"id": "d0", "rect": {"x": 0.625, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "Çuha çiçekleri", "en": "Primroses"}, "text": {"tr": "Saksıdaki pembe çiçekler ve geniş yapraklar.", "en": "Pink flowers and broad leaves in the pot."}}, {"id": "d1", "rect": {"x": 0.25, "y": 0.625, "w": 0.5, "h": 0.375}, "title": {"tr": "Örtü", "en": "The cloth"}, "text": {"tr": "Beyaz örtünün kıvrımları masada dalgalanır.", "en": "The folds of the white cloth ripple across the table."}}]}, "met-436946": {"title": {"tr": "Çörek (La Brioche)", "en": "The Brioche"}, "note": {"tr": "Manet, Fransız natürmort ustası Chardin'e saygı olarak bu konuyu seçti. Çöreğin tepesine yerleştirilmiş çiçek, sade bir sofraya zarif bir dokunuş katar.", "en": "Manet chose this subject in homage to the French still-life master Chardin. The flower set on top of the brioche adds an elegant touch to a simple table."}, "details": [{"id": "d0", "rect": {"x": 0.375, "y": 0.125, "w": 0.25, "h": 0.25}, "title": {"tr": "Çiçek", "en": "The flower"}, "text": {"tr": "Çöreğin tepesinde bir gül.", "en": "A rose on top of the brioche."}}, {"id": "d1", "rect": {"x": 0.5, "y": 0.375, "w": 0.25, "h": 0.25}, "title": {"tr": "Şeftaliler", "en": "Peaches"}, "text": {"tr": "Sağdaki şeftaliler ve erikler.", "en": "Peaches and plums on the right."}}]}};
